#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioWrite(GPIO_2, 1);
        gpioWrite(GPIO_3, 0);
        printf("GPIO 2: HIGH, GPIO 3: LOW\n");
        gpioDelay(100000); // 0.1 seconds

        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
        printf("GPIO 2: LOW, GPIO 3: HIGH\n");
        gpioDelay(100000); // 0.1 seconds
    }

    gpioWrite(GPIO_2, 0);
    gpioWrite(GPIO_3, 0);

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", GPIO_VALUE) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {5, 0}; // 5 seconds
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, GPIO_VALUE);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0080  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

        if (write_ads1115(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t conversion;
        if (read_ads1115(i2c_fd, ADS1115_REG_CONVERT, &conversion) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Print the raw ADC value
        printf("Raw ADC Value: %d\n", conversion);

        // Wait for 0.5 seconds
        sleep(1);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// MLX90614 I2C address
#define MLX90614_ADDR 0x5A

// MLX90614 register addresses
#define MLX90614_TA 0x06  // Ambient temperature
#define MLX90614_TO 0x07  // Object temperature

// I2C bus
#define I2C_BUS 1

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from MLX90614
float read_temperature(int handle) {
    int raw_data;
    float temperature;

    // Read ambient temperature
    raw_data = i2cReadWordData(handle, MLX90614_TA);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading ambient temperature: %s\n", strerror(errno));
        return -273.15; // Return absolute zero on error
    }
    temperature = (raw_data * 0.02) - 273.15;

    return temperature;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature(i2c_handle);

        if (temperature > -273.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check I2C connection.\n");
        }

        sleep(5);
    }

    // Cleanup (should not reach here due to the signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

