#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static int running = 1;

void cleanup(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    running = 0;
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO17)");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line17, "myprogram", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line18, "myprogram", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 17: %d\n", gpiod_line_get_value(line17));
    printf("GPIO 18: %d\n", gpiod_line_get_value(line18));

    gpiod_line_release(line17);
    gpiod_line_release(line18);
