#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, rc;
    int pi;

    /* Initialize pigpio */
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pi);
        return 1;
    }

    /* Set GPIO mode to output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Set PWM frequency */
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    /* Set PWM range */
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        for (i = 0; i <= PWM_RANGE; i++) {
            gpioPWM(GPIO_PIN, i);
            printf("PWM Duty Cycle: %d\n", i);
            gpioDelay(500000); // 0.5 seconds
        }
        for (i = PWM_RANGE; i >= 0; i--) {
            gpioPWM(GPIO_PIN, i);
            printf("PWM Duty Cycle: %d\n", i);
            gpioDelay(500000); // 0.5 seconds
        }
    }

    /* Clean up */
    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
