        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup_gpio();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

