// Define the GPIO pins to be used
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

// Define the number of cycles to run
#define NUM_CYCLES 256

// Define the delay between cycles in microseconds
#define DELAY_US 1000

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line8, *line9, *line10, *line11, *line23, *line24;

// Flag to indicate if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO line
int get_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to print the state of all GPIO lines
void print_gpio_state() {
    int state8 = get_gpio_state(line8);
    int state9 = get_gpio_state(line9);
    int state10 = get_gpio_state(line10);
    int state11 = get_gpio_state(line11);
    int state23 = get_gpio_state(line23);
    int state24 = get_gpio_state(line24);

    if (state8 < 0 || state9 < 0 || state10 < 0 || state11 < 0 || state23 < 0 || state24 < 0) {
        fprintf(stderr, "Error reading GPIO states.\n");
        return;
    }

    printf("GPIO 8: %d, GPIO 9: %d, GPIO 10: %d, GPIO 11: %d, GPIO 23: %d, GPIO 24: %d\n",
           state8, state9, state10, state11, state23, state24);
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line9 = gpiod_chip_get_line(chip, GPIO_9);
    line10 = gpiod_chip_get_line(chip, GPIO_10);
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line8 || !line9 || !line10 || !line11 || !line23 || !line24) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Request the lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line8, &config, 0) < 0 ||
        gpiod_line_request(line9, &config, 0) < 0 ||
        gpiod_line_request(line10, &config, 0) < 0 ||
        gpiod_line_request(line11, &config, 0) < 0 ||
        gpiod_line_request(line23, &config, 0) < 0 ||
        gpiod_line_request(line24, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES && program_running; ++i) {
        // Set the GPIO states
        if (set_gpio_state(line8, i % 2) < 0 ||
            set_gpio_state(line9, (i + 1) % 2) < 0 ||
            set_gpio_state(line10, (i + 2) % 2) < 0 ||
            set_gpio_state(line11, (i + 3) % 2) < 0 ||
            set_gpio_state(line23, (i + 4) % 2) < 0 ||
            set_gpio_state(line24, (i + 5) % 2) < 0) {
            fprintf(stderr, "Error setting GPIO state.\n");
            goto cleanup;
        }

        // Print the GPIO states
        print_gpio_state();

        // Delay
        struct timespec delay = {0, DELAY_US * 1000};
        nanosleep(&delay, NULL);
    }

cleanup:
    // Release the lines
    if (line8) gpiod_line_release(line8);
    if (line9) gpiod_line_release(line9);
    if (line10) gpiod_line_release(line10);
    if (line11) gpiod_line_release(line11);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    return 0;
}

