#define GPIO_11 11

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_10, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Set GPIO 8 HIGH
        gpioWrite(GPIO_8, 1);
        printf("GPIO 8: HIGH\n");

        // Set GPIO 9 LOW
        gpioWrite(GPIO_9, 0);
        printf("GPIO 9: LOW\n");

        // Set GPIO 10 HIGH
        gpioWrite(GPIO_10, 1);
