#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void report_distance(double distance);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "hc-sr04", 0);
    if (ret < 0) {
        perror("Error requesting trigger line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "hc-sr04");
    if (ret < 0) {
        perror("Error requesting echo line for input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger a 10us pulse on the trigger pin
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    struct timespec ts = {0, 10000}; // 10us
    nanosleep(&ts, NULL);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo to go high
    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }
    while (ret == 0) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        pulse_width++;
        struct timespec ts = {0, 1}; // 1us
        nanosleep(&ts, NULL);
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }
    while (ret == 1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        pulse_width++;
        struct timespec ts = {0, 1}; // 1us
        nanosleep(&ts, NULL);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Report the distance to standard output
void report_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width. Retrying.\n");
            sleep(1);
            continue;
        }

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Report the distance
        report_distance(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

