#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUDRATE B115200
#define TIMEOUT_SEC 1
#define TIMEOUT_USEC 0

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int setup_serial(const char *device, speed_t baudrate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baudrate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from serial port");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    serial_fd = setup_serial(DEVICE, BAUDRATE);
    if (serial_fd == -1) {
        fprintf(stderr, "Failed to setup serial communication.\n");
        return 1;
    }

    char buffer[256];
    ssize_t bytes_read;

    fprintf(stderr, "Reading from serial port %s at %d baud.\n", DEVICE, BAUDRATE);

    while (program_running) {
        bytes_read = read_data(serial_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("%s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading data, exiting.\n");
            break;
        }
    }

    if (serial_fd != -1) {
        close(serial_fd);
    }

    fprintf(stderr, "Program finished.\n");
    return 0;
}

