#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17, *line22, *line27;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

static int set_gpio_state(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO_4, &line4) ||
        setup_gpio(GPIO_17, &line17) ||
        setup_gpio(GPIO_22, &line22) ||
        setup_gpio(GPIO_27, &line27)) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = set_gpio_state(line4, 1);
    if (ret < 0) goto cleanup;
    ret = set_gpio_state(line17, 0);
    if (ret < 0) goto cleanup;
    ret = set_gpio_state(line22, 1);
    if (ret < 0) goto cleanup;
    ret = set_gpio_state(line27, 0);
    if (ret < 0) goto cleanup;

    printf("GPIO 4: %d, GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
           gpiod_line_get_value(line4),
           gpiod_line_get_value(line17),
           gpiod_line_get_value(line22),
           gpiod_line_get_value(line27));

cleanup:
    cleanup_gpio(line4);
    cleanup_gpio(line17);
    cleanup_gpio(line22);
    cleanup_gpio(line27);
    gpiod_chip_close(chip);

    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

