#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT11_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(gpio, 1);
    gpioDelay(20); // 20us

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT11 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Check every 1us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100us
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1;
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1;
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1;
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht11(DHT11_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT11 read failed with error code: %d\n", result);
        }

        sleep(5);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

