#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip;
static struct gpiod_line *line2, *line3;
static int running = 1;

// Function prototypes
int setup_gpio(int gpio);
int set_gpio_output(int gpio, int value);
int get_gpio_value(int gpio);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set up a GPIO pin as output
int setup_gpio(int gpio) {
    struct gpiod_line_request_config config;
    int ret;

    // Request the GPIO line
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpio == GPIO_2) {
        line2 = gpiod_chip_get_line(chip, gpio);
        if (!line2) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio, strerror(errno));
            return -1;
        }
        ret = gpiod_line_request(line2, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else if (gpio == GPIO_3) {
        line3 = gpiod_chip_get_line(chip, gpio);
        if (!line3) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio, strerror(errno));
            return -1;
        }
        ret = gpiod_line_request(line3, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO pin
int set_gpio_output(int gpio, int value) {
    int ret;

    if (gpio == GPIO_2) {
        ret = gpiod_line_set_value(line2, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting value for GPIO %d: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else if (gpio == GPIO_3) {
        ret = gpiod_line_set_value(line3, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting value for GPIO %d: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    return 0;
}

// Function to get the value of a GPIO pin
int get_gpio_value(int gpio) {
    int value;

    if (gpio == GPIO_2) {
        value = gpiod_line_get_value(line2);
        if (value < 0) {
            fprintf(stderr, "Error getting value for GPIO %d: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else if (gpio == GPIO_3) {
        value = gpiod_line_get_value(line3);
        if (value < 0) {
            fprintf(stderr, "Error getting value for GPIO %d: %s\n", gpio, strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    return value;
}

// Function to clean up GPIO resources
void cleanup_gpio(void) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i, value2, value3;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pins as output
    if (setup_gpio(GPIO_2) < 0) {
        cleanup_gpio();
        return 1;
    }
    if (setup_gpio(GPIO_3) < 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES && running; i++) {
        // Set GPIO 2 to HIGH
        if (set_gpio_output(GPIO_2, 1) < 0) {
            cleanup_gpio();
            return 1;
        }
        // Set GPIO 3 to LOW
        if (set_gpio_output(GPIO_3, 0) < 0) {
            cleanup_gpio();
            return 1;
        }

        // Wait for 5 seconds
        sleep(5);

        // Get the value of GPIO 2
        value2 = get_gpio_value(GPIO_2);
        if (value2 < 0) {
            cleanup_gpio();
            return 1;
        }

        // Get the value of GPIO 3
        value3 = get_gpio_value(GPIO_3);
        if (value3 < 0) {
            cleanup_gpio();
            return 1;
        }

        // Print the values to standard output
        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d\n", i + 1, value2, value3);
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

