// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Set GPIO 2 to HIGH
        gpioWrite(GPIO_2, 1);
        printf("GPIO 2: HIGH\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms

        // Set GPIO 2 to LOW
        gpioWrite(GPIO_2, 0);
        printf("GPIO 2: LOW\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms

        // Set GPIO 3 to HIGH
        gpioWrite(GPIO_3, 1);
        printf("GPIO 3: HIGH\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms

        // Set GPIO 3 to LOW
        gpioWrite(GPIO_3, 0);
        printf("GPIO 3: LOW\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms

        // Set GPIO 17 to HIGH
        gpioWrite(GPIO_17, 1);
        printf("GPIO 17: HIGH\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms

        // Set GPIO 17 to LOW
        gpioWrite(GPIO_17, 0);
        printf("GPIO 17: LOW\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

