#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(int signal)
{
    printf("\nCleaning up and exiting...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, cleanup);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set initial state */
    ret = gpiod_line_set_value(line, current_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO value: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d (BCM %d) is now set to %d\n", GPIO_PIN, GPIO_PIN, current_state);

    /* Toggle state every 1 second */
    while (1) {
        current_state = !current_state;
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            cleanup(0);
            return 1;
        }
        printf("GPIO %d (BCM %d) is now set to %d\n", GPIO_PIN, GPIO_PIN, current_state);
        sleep(1);
    }

    return 0;
}

