#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Request GPIO line for output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Set initial state */
    ret = gpiod_line_set_value(line, current_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO value: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("GPIO %d (BCM %d) is now %s\n", GPIO_LINE, GPIO_LINE, current_state ? "HIGH" : "LOW");

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

int i2c_fd = -1;

void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure OPT3001 for continuous conversion mode
    uint16_t config_value = 0xCC10; // Continuous conversion mode, 100ms conversion time
    uint8_t config_data[2];
    config_data[0] = (config_value >> 8) & 0xFF;
    config_data[1] = config_value & 0xFF;

    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error writing to configuration register");
        close(i2c_fd);
        return 1;
    }

    // Wait for conversion to complete (at least 100ms)
    usleep(100000); // 100ms

    // Read the result register
    uint8_t result_data[2];
    if (read(i2c_fd, result_data, 2) != 2) {
        perror("Error reading from result register");
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_result = (result_data[0] << 8) | result_data[1];

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    int result = raw_result & 0x0FFF;

    // Calculate lux value
    float lux = result * (0.01 * (1 << exponent));

    printf("Lux: %.2f\n", lux);

    close(i2c_fd);
    return 0;
}

