#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_PATH "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define TIMEOUT_SEC 1
#define TIMEOUT_USEC 0

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

void cleanup() {
    if (serial_fd != -1) {
        close(serial_fd);
        fprintf(stderr, "Serial port closed.\n");
    }
}

int main() {
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;
    time_t start_time, current_time;
    double elapsed_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open serial port
    serial_fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        perror("Error opening serial port");
        return 1;
    }
    fprintf(stderr, "Serial port opened successfully.\n");

    // Configure serial port
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        cleanup();
        return 1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 0;                             // No timeout

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Serial port configured.\n");

    // Main loop
    time(&start_time);
    while (program_running) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            time(&start_time); // Reset timeout
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout occurred
                time(&current_time);
                elapsed_time = difftime(current_time, start_time);
                if (elapsed_time >= TIMEOUT_SEC) {
                    fprintf(stderr, "Timeout occurred. No data received for %f seconds.\n", elapsed_time);
                    program_running = 0; // Exit after timeout
                }
            } else {
                perror("Error reading from serial port");
                program_running = 0; // Exit on error
            }
        } else {
            // No data received, check timeout
            time(&current_time);
            elapsed_time = difftime(current_time, start_time);
            if (elapsed_time >= TIMEOUT_SEC) {
                fprintf(stderr, "Timeout occurred. No data received for %f seconds.\n", elapsed_time);
                program_running = 0; // Exit after timeout
            }
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }

    cleanup();
    return 0;
}

