#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_VALUE 1
#define CYCLE_DURATION 60 // seconds

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", GPIO_VALUE) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int set_gpio_value(int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int validate_gpio_value(int value)
{
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value: %d\n", value);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct timespec sleep_time = {CYCLE_DURATION, 0};
    struct timespec remaining_time;
    int i;

    signal(SIGINT, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3 && !terminate; ++i) {
        if (set_gpio_value(GPIO_VALUE) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (validate_gpio_value(GPIO_VALUE) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

