#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18, *line22, *line27;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, int value)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    switch (gpio) {
    case GPIO_17:
        line17 = gpiod_chip_get_line(chip, GPIO_17);
        if (!line17) {
            fprintf(stderr, "Error: Could not get line %d\n", GPIO_17);
            return -1;
        }
        ret = gpiod_line_request(line17, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_17);
            return -1;
        }
        gpiod_line_set_value(line17, value);
        break;
    case GPIO_18:
        line18 = gpiod_chip_get_line(chip, GPIO_18);
        if (!line18) {
            fprintf(stderr, "Error: Could not get line %d\n", GPIO_18);
            return -1;
        }
        ret = gpiod_line_request(line18, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_18);
            return -1;
        }
        gpiod_line_set_value(line18, value);
        break;
    case GPIO_22:
        line22 = gpiod_chip_get_line(chip, GPIO_22);
        if (!line22) {
            fprintf(stderr, "Error: Could not get line %d\n", GPIO_22);
            return -1;
        }
        ret = gpiod_line_request(line22, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_22);
            return -1;
        }
        gpiod_line_set_value(line22, value);
        break;
    case GPIO_27:
        line27 = gpiod_chip_get_line(chip, GPIO_27);
        if (!line27) {
            fprintf(stderr, "Error: Could not get line %d\n", GPIO_27);
            return -1;
        }
        ret = gpiod_line_request(line27, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_27);
            return -1;
        }
        gpiod_line_set_value(line27, value);
        break;
    default:
        fprintf(stderr, "Error: Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO_17, 0) < 0 ||
        setup_gpio(GPIO_18, 1) < 0 ||
        setup_gpio(GPIO_22, 0) < 0 ||
        setup_gpio(GPIO_27, 1) < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        printf("GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 27: %d\n",
               gpiod_line_get_value(line17),
               gpiod_line_get_value(line18),
               gpiod_line_get_value(line22),
               gpiod_line_get_value(line27));
        fflush(stdout);
        sleep(1);
    }

    cleanup_gpio();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

