static void cleanup(int sig)
{
    printf("\nCleaning up and exiting...\n");
    if (line11) gpiod_line_release(line11);
    if (line12) gpiod_line_release(line12);
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int value;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, cleanup);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO lines */
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line12 = gpiod_chip_get_line(chip, GPIO_12);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line11 || !line12 || !line17 || !line18) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    /* Request GPIO lines for output */
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line11, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 11");
        cleanup(0);
        return 1;
    }

    ret = gpiod_line_request(line12, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 12");
        cleanup(0);
        return 1;
    }

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        cleanup(0);
        return 1;
    }

    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        cleanup(0);
        return 1;
    }

    /* Main loop */
    while (1) {
        /* Set GPIO states */
        gpiod_line_set_value(line11, 1);
        gpiod_line_set_value(line12, 0);
        gpiod_line_set_value(line17, 1);
        gpiod_line_set_value(line18, 0);

        /* Print GPIO states */
        printf("GPIO 11: %d, GPIO 12: %d, GPIO 17: %d, GPIO 18: %d\n",
               gpiod_line_get_value(line11),
               gpiod_line_get_value(line12),
               gpiod_line_get_value(line17),
               gpiod_line_get_value(line18));

        /* Wait for 0.1 seconds */
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

