{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate)
    {
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_22, 0);
        gpioWrite(GPIO_27, 1);
        printf("GPIO 17: ON, GPIO 22: OFF, GPIO 27: ON\n");
        gpioDelay(100000); // 0.1 seconds

        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_22, 1);
        gpioWrite(GPIO_27, 0);
        printf("GPIO 17: OFF, GPIO 22: ON, GPIO 27: OFF\n");
        gpioDelay(100000); // 0.1 seconds
    }

    gpioTerminate();
    printf("Program terminated cleanly\n");
    return 0;
}

