    ret = gpiod_line_request(line4, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO4)");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO17)");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 4: %d\n", gpiod_line_get_value(line4));
    printf("GPIO 17: %d\n", gpiod_line_get_value(line17));

    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    return 0;
}

