#include <errno.h>
#include <time.h>
#include <sys/time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        printf("\nExiting gracefully...\n");
    }
}

// Function to get the DS18B20 device ID
char* get_ds18b20_id() {
    DIR *dir;
    struct dirent *ent;
    char *id = NULL;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return NULL;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            id = strdup(ent->d_name); // Allocate memory for the ID
            if (id == NULL) {
                perror("Error allocating memory for device ID");
                closedir(dir);
                return NULL;
            }
            break; // Found the first DS18B20 device
        }
    }

    closedir(dir);
    return id;
}

// Function to read the temperature from the DS18B20
float read_temperature(const char *device_id) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening " W1_SLAVE_FILE);
        return -1000.0; // Indicate an error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Error reading " W1_SLAVE_FILE);
        return -1000.0; // Indicate an error
    }
    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1000.0; // Indicate an error
    }

    // Extract temperature
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", W1_SLAVE_FILE);
        return -1000.0; // Indicate an error
    }

    long temperature_raw = strtol(temp_str + 2, NULL, 10);
    float temperature = (float)temperature_raw / 1000.0;

    return temperature;
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    char *device_id = get_ds18b20_id();
    if (device_id == NULL) {
        fprintf(stderr, "DS18B20 device not found. Please ensure it is connected and the w1-gpio module is loaded.\n");
        return 1;
    }

    printf("DS18B20 device ID: %s\n", device_id);

    while (program_running) {
        float temperature = read_temperature(device_id);

        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds.\n");
        }

        sleep(5);
    }

    free(device_id);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
