#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define TEMP_MEASURE_HOLD 0xE3
#define HUMID_MEASURE_HOLD 0xE5

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int read_htu21d(int fd, uint16_t *temperature, uint16_t *humidity) {
    uint8_t buf[3];
    uint16_t raw_temp, raw_humidity;

    // Temperature measurement
    if (write(fd, &TEMP_MEASURE_HOLD, 1) != 1) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (read(fd, buf, 3) != 3) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    raw_temp = (buf[0] << 8) | buf[1];
    if (raw_temp > 65535) return -1; // Check for overflow

    // Humidity measurement
    if (write(fd, &HUMID_MEASURE_HOLD, 1) != 1) {
        fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (read(fd, buf, 3) != 3) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];
    if (raw_humidity > 65535) return -1; // Check for overflow

    *temperature = raw_temp;
    *humidity = raw_humidity;

    return 0;
}

int main() {
    uint16_t temperature, humidity;
    float temp_celsius, humidity_percent;
    const char *i2c_device = "/dev/i2c-1";

    signal(SIGINT, signal_handler);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (read_htu21d(i2c_fd, &temperature, &humidity) == 0) {
            temp_celsius = -46.85 + 175.72 * ((float)temperature / 65536.0);
            humidity_percent = -6.0 + 125.0 * ((float)humidity / 65536.0);

            if (temp_celsius > -50.0 && temp_celsius < 100.0 && humidity_percent > 0.0 && humidity_percent < 100.0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_celsius, humidity_percent);
            } else {
                fprintf(stderr, "Invalid sensor reading. Skipping.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(60);
    }

    close(i2c_fd);
    return 0;
}

