#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3

static struct gpiod_chip *chip;
static struct gpiod_line *line2, *line3;

static void cleanup(int sig)
{
	printf("\nCleaning up and exiting...\n");
	if (line2) {
		gpiod_line_set_value(line2, 0);
		gpiod_line_release(line2);
	}
	if (line3) {
		gpiod_line_set_value(line3, 0);
		gpiod_line_release(line3);
	}
	if (chip) {
		gpiod_chip_close(chip);
	}
	exit(0);
}

int main()
{
	int ret;

	/* Open GPIO chip */
	chip = gpiod_chip_open_by_name(GPIO_CHIP);
	if (!chip) {
		perror("gpiod_chip_open_by_name");
		return 1;
	}

	/* Get GPIO 2 line */
	line2 = gpiod_chip_get_line(chip, GPIO_2);
	if (!line2) {
		perror("gpiod_chip_get_line (GPIO 2)");
		gpiod_chip_close(chip);
		return 1;
	}

	/* Get GPIO 3 line */
	line3 = gpiod_chip_get_line(chip, GPIO_3);
	if (!line3) {
		perror("gpiod_chip_get_line (GPIO 3)");
		gpiod_line_release(line2);
		gpiod_chip_close(chip);
		return 1;
	}

	/* Request GPIO 2 as output */
	ret = gpiod_line_request_output(line2, "my_program", 0);
	if (ret < 0) {
		perror("gpiod_line_request_output (GPIO 2)");
		gpiod_line_release(line2);
		gpiod_line_release(line3);
		gpiod_chip_close(chip);
		return 1;
	}

	/* Request GPIO 3 as output */
	ret = gpiod_line_request_output(line3, "my_program", 0);
	if (ret < 0) {
		perror("gpiod_line_request_output (GPIO 3)");
		gpiod_line_release(line2);
		gpiod_line_release(line3);
		gpiod_chip_close(chip);
		return 1;
	}

	/* Set up signal handler for Ctrl+C */
	signal(SIGINT, cleanup);

	/* Main loop */
	while (1) {
		/* Set GPIO 2 high */
		ret = gpiod_line_set_value(line2, 1);
		if (ret < 0) {
			perror("gpiod_line_set_value (GPIO 2)");
			break;
		}
		printf("GPIO 2 set high\n");

		/* Set GPIO 3 low */
		ret = gpiod_line_set_value(line3, 0);
		if (ret < 0) {
			perror("gpiod_line_set_value (GPIO 3)");
			break;
		}
		printf("GPIO 3 set low\n");

		/* Wait 2 seconds */
		sleep(2);

		/* Set GPIO 2 low */
		ret = gpiod_line_set_value(line2, 0);
		if (ret < 0) {
			perror("gpiod_line_set_value (GPIO 2)");
			break;
		}
		printf("GPIO 2 set low\n");

		/* Set GPIO 3 high */
		ret = gpiod_line_set_value(line3, 1);
		if (ret < 0) {
			perror("gpiod_line_set_value (GPIO 3)");
			break;
		}
		printf("GPIO 3 set high\n");

		/* Wait 2 seconds */
		sleep(2);
	}

	/* Cleanup and exit */
	cleanup(0);

	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two consecutive registers
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345: set POWER_CTL register to 0x08 (measurement mode)
    if (i2c_write_byte(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (i2c_read_word(i2c_fd, ADXL345_DATAX0, &x) < 0 ||
            i2c_read_word(i2c_fd, ADXL345_DATAY0, &y) < 0 ||
            i2c_read_word(i2c_fd, ADXL345_DATAZ0, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            close(i2c_fd);
            return 1;
        }

        // Print accelerometer data
        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

