#include <gpiod.h>
#include <time.h>

#define NUM_GPIOS 4
const int gpios[NUM_GPIOS] = {17, 22, 23, 24};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
int running = 1;

void cleanup() {
    printf("Cleaning up...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int ret;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request lines for input
    for (int i = 0; i < NUM_GPIOS; i++) {
        config.consumer = "dht22_reader";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d\n", gpios[i]);
            cleanup();
            return 1;
        }

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d\n", gpios[i]);
            cleanup();
            return 1;
        }
    }

    printf("DHT22 reader started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_event_wait(lines[i], NULL, NULL, 0);
            if (ret < 0) {
                fprintf(stderr, "Error waiting for event on line %d\n", gpios[i]);
                continue; // Try the next GPIO
            }

            ret = gpiod_line_event_read(lines[i], &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading event on line %d\n", gpios[i]);
                continue; // Try the next GPIO
            }

            printf("GPIO %d: %s\n", gpios[i], (event.value == 1) ? "HIGH" : "LOW");
        }
        sleep(2);
    }

    cleanup();
    return 0;
}

