    terminate = 1;
}

int main() {
    int i, rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO mode to output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Set PWM frequency */
