            printf("PWM Duty Cycle: %d\n", i);
            gpioDelay(20000); // 20ms delay
        }
        for (i = PWM_RANGE; i >= 0; i--) {
            gpioPWM(GPIO_PIN, i);
            printf("PWM Duty Cycle: %d\n", i);
            gpioDelay(20000); // 20ms delay
        }
    }

    /* Clean up and exit */
    gpioTerminate();
