#define GPIO_23 23
#define GPIO_24 24

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    while (program_running) {
        // Set GPIO 17 HIGH
        gpioWrite(GPIO_17, 1);
        printf("GPIO 17: HIGH\n");

        // Set GPIO 22 LOW
        gpioWrite(GPIO_22, 0);
        printf("GPIO 22: LOW\n");

        // Set GPIO 23 HIGH
        gpioWrite(GPIO_23, 1);
        printf("GPIO 23: HIGH\n");

        // Set GPIO 24 LOW
        gpioWrite(GPIO_24, 0);
        printf("GPIO 24: LOW\n");

        gpioDelay(200); // 0.2 seconds
    }

    // Clean up GPIO pins before exiting
    gpioWrite(GPIO_17, 0);
    gpioWrite(GPIO_22, 0);
    gpioWrite(GPIO_23, 0);
    gpioWrite(GPIO_24, 0);

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the TCS34725
int read_16bit_value(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (buffer[1] << 8) | buffer[0];
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Enable the TCS34725
    uint8_t enable_value = 0x03; // Power on and enable RGBC
    if (write(i2c_fd, &enable_value, 1) != 1) {
        fprintf(stderr, "Error writing to enable register: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set integration time (ATIME).  A longer integration time gives better lux measurement
    uint8_t atime_value = 0xD5; // 101ms integration time
    if (write(i2c_fd, &atime_value, 1) != 1) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read color data
        int clear = read_16bit_value(i2c_fd, TCS34725_CDATA);
        int red = read_16bit_value(i2c_fd, TCS34725_RDATA);
        int green = read_16bit_value(i2c_fd, TCS34725_GDATA);
        int blue = read_16bit_value(i2c_fd, TCS34725_BDATA);

        if (clear == -1 || red == -1 || green == -1 || blue == -1) {
            fprintf(stderr, "Error reading color data. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Print color data
        printf("C: %d, R: %d, G: %d, B: %d\n", clear, red, green, blue);

        // Wait 200ms
        usleep(200000);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_21, *line_22;

// Function prototypes
int setup_gpio(int gpio_pin);
int set_gpio_output(int gpio_pin, int value);
int cleanup_gpio(int gpio_pin);
void signal_handler(int sig);

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(GPIO_18);
    cleanup_gpio(GPIO_21);
    cleanup_gpio(GPIO_22);
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to setup a GPIO pin as output
int setup_gpio(int gpio_pin) {
    struct gpiod_line_request_config config;
    int ret;

    // Request the GPIO line
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    switch (gpio_pin) {
        case GPIO_18:
            ret = gpiod_line_request(line_18, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d as output: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_21:
            ret = gpiod_line_request(line_21, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d as output: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_22:
            ret = gpiod_line_request(line_22, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d as output: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO pin
int set_gpio_output(int gpio_pin, int value) {
    int ret;

    switch (gpio_pin) {
        case GPIO_18:
            ret = gpiod_line_set_value(line_18, value);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO %d value: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_21:
            ret = gpiod_line_set_value(line_21, value);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO %d value: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_22:
            ret = gpiod_line_set_value(line_22, value);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO %d value: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    return 0;
}

// Function to cleanup a GPIO pin
int cleanup_gpio(int gpio_pin) {
    int ret;

    switch (gpio_pin) {
        case GPIO_18:
            ret = gpiod_line_release(line_18);
            if (ret < 0) {
                fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_21:
            ret = gpiod_line_release(line_21);
            if (ret < 0) {
                fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        case GPIO_22:
            ret = gpiod_line_release(line_22);
            if (ret < 0) {
                fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pin, strerror(-ret));
                return -1;
            }
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_21 = gpiod_chip_get_line(chip, GPIO_21);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);

    if (!line_18 || !line_21 || !line_22) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Setup GPIO pins as output
    if (setup_gpio(GPIO_18) < 0 || setup_gpio(GPIO_21) < 0 || setup_gpio(GPIO_22) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial output values
    set_gpio_output(GPIO_18, 0);
    set_gpio_output(GPIO_21, 1);
    set_gpio_output(GPIO_22, 0);

    // Print the current state of each GPIO pin
    printf("GPIO 18: %d\n", gpiod_line_get_value(line_18));
    printf("GPIO 21: %d\n", gpiod_line_get_value(line_21));
    printf("GPIO 22: %d\n", gpiod_line_get_value(line_22));

    // Cleanup and exit
    cleanup_gpio(GPIO_18);
    cleanup_gpio(GPIO_21);
    cleanup_gpio(GPIO_22);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // Assuming YUYV format

static int fd = -1;
static unsigned char *buffer = NULL;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    FILE *fp;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming.\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Generate filename with timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuv", timeinfo);

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        ioctl(fd, VIDIOC_QBUF, &buf);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, IMAGE_SIZE, fp);
    fclose(fp);

    printf("Captured image saved to %s\n", filename);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    munmap(buffer, buf.length);
    close(fd);

    return 0;
}

