#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SSD1306_ADDR 0x3C

// Define the display dimensions
#define WIDTH 128
#define HEIGHT 64

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Function to write a command to the SSD1306
void ssd1306_write_command(uint8_t command) {
  uint8_t buffer[2];
  buffer[0] = 0x00; // Control byte: command
  buffer[1] = command;
  if (write(i2c_fd, buffer, 2) != 2) {
    perror("Failed to write command");
  }
}

// Function to write data to the SSD1306
void ssd1306_write_data(uint8_t data) {
  uint8_t buffer[2];
  buffer[0] = 0x40; // Control byte: data
  buffer[1] = data;
  if (write(i2c_fd, buffer, 2) != 2) {
    perror("Failed to write data");
  }
}

// Function to initialize the SSD1306
void ssd1306_init() {
  ssd1306_write_command(0xAE); // Display off
  ssd1306_write_command(0xD5); // Set display clock divide ratio/oscillator frequency
  ssd1306_write_command(0x80); // --ratio
  ssd1306_write_command(0xA8); // Set multiplex ratio
  ssd1306_write_command(0x3F); // --ratio
  ssd1306_write_command(0xD3); // Set display offset
  ssd1306_write_command(0x00); // --offset
  ssd1306_write_command(0x40); // Set start line address
  ssd1306_write_command(0x8D); // Charge pump setting
  ssd1306_write_command(0x14); // --enable
  ssd1306_write_command(0x20); // Set memory addressing mode
  ssd1306_write_command(0x00); // --horizontal addressing mode
  ssd1306_write_command(0xA1); // Set segment re-map
  ssd1306_write_command(0xC8); // Set COM output scan direction
  ssd1306_write_command(0xDA); // Set COM pins hardware configuration
  ssd1306_write_command(0x12); // --configuration
  ssd1306_write_command(0x81); // Set contrast control
  ssd1306_write_command(0xCF); // --contrast
  ssd1306_write_command(0xD9); // Set pre-charge period
  ssd1306_write_command(0xF1); // --period
  ssd1306_write_command(0xDB); // Set VCOM deselect level
  ssd1306_write_command(0x40); // --level
  ssd1306_write_command(0xA4); // Entire display ON/OFF
  ssd1306_write_command(0xA6); // Set normal display
  ssd1306_write_command(0xAF); // Display on
}

// Function to clear the display
void ssd1306_clear() {
  for (int i = 0; i < (WIDTH * HEIGHT / 8); i++) {
    ssd1306_write_data(0x00);
  }
}

// Function to display a string on the display
void ssd1306_display_string(int x, int y, const char *str) {
  // This is a placeholder.  A real implementation would
  // convert the string to a bitmap and write it to the display.
  // For simplicity, we'll just print the string to the console.
  printf("Displaying string '%s' at (%d, %d)\n", str, x, y);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
  printf("Caught signal %d, cleaning up...\n", sig);
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  exit(0);
}

int main() {
  // Register the signal handler
  signal(SIGINT, signal_handler);

  // Open the I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set the I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize the SSD1306
  ssd1306_init();

  // Main loop
  while (1) {
    // Get the current time
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the time as a string
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Display the time string
    ssd1306_display_string(0, 0, time_str);

    // Clear the display
    ssd1306_clear();

    // Wait for 0.1 seconds
    usleep(100000); // 100000 microseconds = 0.1 seconds
  }

  return 0;
}

#include <stdio.h>
