        if (ret < 0) {
            perror("Error setting GPIO 3 low");
            cleanup();
            return 1;
        }
        printf("GPIO 3: LOW\n");

        /* Set GPIO 5 high */
        ret = gpiod_line_set_value(line5, 1);
        if (ret < 0) {
            perror("Error setting GPIO 5 high");
            cleanup();
            return 1;
        }
        printf("GPIO 5: HIGH\n");

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency for each GPIO pin
    gpioSetPWMfrequency(GPIO_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_11, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Main loop
    while (1) {
        // Generate PWM signals with different duty cycles
        gpioPWM(GPIO_8, 0);   // GPIO 8: 0%
        gpioPWM(GPIO_9, 128); // GPIO 9: 50%
        gpioPWM(GPIO_11, 255); // GPIO 11: 100%
        gpioPWM(GPIO_18, 0);   // GPIO 18: 0%

        // Print the PWM state to standard output
        printf("GPIO 8: %d, GPIO 9: %d, GPIO 11: %d, GPIO 18: %d\n", 0, 128, 255, 0);

        // Wait for 1 second
        sleep(1);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define LED_PIN 24

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
void signalHandler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(TRIGGER_PIN, PI_INPUT); // Set back to input
    gpioSetMode(ECHO_PIN, PI_INPUT);    // Set back to input
    gpioSetMode(LED_PIN, PI_INPUT);     // Set back to input
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger the sensor
        triggerSensor();

        // Wait for a short period
        gpioDelay(200); // 200ms delay

        // Calculate distance
        unsigned int diff = end_tick - start_tick;
        if (diff > TIMEOUT_US) {
            printf("Timeout: No echo received\n");
        } else {
            float time_taken = (float)diff / 1000000.0; // Time in seconds
            float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

            // Print the distance
            printf("Distance: %.2f cm\n", distance);

            // Control LED based on distance
            if (distance < 20.0) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

