#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(int sig)
{
    printf("\nCleaning up and exiting...\n");
    if (line) {
        gpiod_line_set_value(line, 0); // Set to low on exit
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, cleanup);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set initial state */
    ret = gpiod_line_set_value(line, current_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO value: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d (BCM %d) is now set to %d\n", GPIO_LINE, GPIO_LINE, current_state);

    /* Clean up and exit */
    cleanup(0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define NUM_GPIOS 8
const int gpios[NUM_GPIOS] = {1, 4, 5, 6, 21, 22, 23, 24};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
int current_state[NUM_GPIOS];

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0); // Set to low
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int i, ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines and set direction to output
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpios[i], strerror(errno));
            cleanup(1);
        }

        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", gpios[i], strerror(errno));
            cleanup(1);
        }
        current_state[i] = 0; // Initialize to low
        gpiod_line_set_value(lines[i], current_state[i]);
    }

    // Print initial state
    printf("Initial GPIO states:\n");
    for (i = 0; i < NUM_GPIOS; i++) {
        printf("GPIO %d: %d\n", gpios[i], current_state[i]);
    }

    // Toggle each GPIO once
    for (i = 0; i < NUM_GPIOS; i++) {
        current_state[i] = !current_state[i];
        gpiod_line_set_value(lines[i], current_state[i]);
    }

    // Print final state
    printf("\nFinal GPIO states:\n");
    for (i = 0; i < NUM_GPIOS; i++) {
        printf("GPIO %d: %d\n", gpios[i], current_state[i]);
    }

    cleanup(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)
#define IMAGE_FILE "captured_image.raw"

static int fd = -1;
static unsigned char *buffer = NULL;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    FILE *fp;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY; // Grayscale
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Capture and save image
    while (!stop) {
        // Dequeue buffer
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Save image to file
        fp = fopen(IMAGE_FILE, "wb");
        if (fp == NULL) {
            perror("Error opening file for writing");
            break;
        }

        fwrite(buffer, 1, IMAGE_SIZE, fp);
        fclose(fp);

        printf("Captured image saved to %s\n", IMAGE_FILE);

        // Requeue buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }

        // Wait 50ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 50000000; // 50ms
        nanosleep(&ts, NULL);
    }

    // Stop streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
    }

    // Unmap buffer
    if (buffer != NULL) {
        if (munmap(buffer, buf.length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // Close device
    if (fd != -1) {
        close(fd);
    }

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUMIDITY 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from a BME280 register
int bme280_read_register(int fd, uint8_t reg_addr) {
    uint8_t buf[1];
    buf[0] = reg_addr;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to a BME280 register
int bme280_write_register(int fd, uint8_t reg_addr, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int bme280_read_calibration_data(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3, uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3, int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6, int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9, uint8_t *dig_H1, int16_t *dig_H2, uint8_t *dig_H3, int16_t *dig_H4, int16_t *dig_H5, uint8_t *dig_H6) {
    uint8_t buffer[32];

    // Read calibration data from registers 0x88 to 0xA1
    for (int i = 0; i < 26; i++) {
        int reg = BME280_REG_CALIB_00 + i;
        uint8_t msb = bme280_read_register(fd, reg);
        uint8_t lsb = bme280_read_register(fd, reg + 1);
        if (msb == -1 || lsb == -1) return -1;
        buffer[i] = (msb << 8) | lsb;
    }

    // Read calibration data from registers 0xE1 to 0xE7
    for (int i = 0; i < 7; i++) {
        int reg = 0xE1 + i;
        uint8_t value = bme280_read_register(fd, reg);
        if (value == -1) return -1;
        buffer[26 + i] = value;
    }

    // Assign calibration data to pointers
    *dig_T1 = (uint16_t)buffer[0];
    *dig_T2 = (int16_t)buffer[1];
    *dig_T3 = (int16_t)buffer[2];
    *dig_P1 = (uint16_t)buffer[3];
    *dig_P2 = (int16_t)buffer[4];
    *dig_P3 = (int16_t)buffer[5];
    *dig_P4 = (int16_t)buffer[6];
    *dig_P5 = (int16_t)buffer[7];
    *dig_P6 = (int16_t)buffer[8];
    *dig_P7 = (int16_t)buffer[9];
    *dig_P8 = (int16_t)buffer[10];
    *dig_P9 = (int16_t)buffer[11];
    *dig_H1 = buffer[25];
    *dig_H2 = (int16_t)buffer[26];
    *dig_H3 = buffer[27];
    *dig_H4 = (int16_t)((buffer[28] << 4) | (buffer[29] & 0x0F));
    *dig_H5 = (int16_t)((buffer[30] << 4) | (buffer[29] >> 4));
    *dig_H6 = buffer[31];

    return 0;
}

// Function to read raw temperature, pressure, and humidity data from the BME280
int bme280_read_raw_data(int fd, int32_t *raw_temp, int32_t *raw_pressure, int32_t *raw_humidity) {
    uint8_t buffer[8];

    // Read temperature data (3 bytes)
    for (int i = 0; i < 3; i++) {
        int reg = BME280_REG_TEMP_MSB + i;
        uint8_t value = bme280_read_register(fd, reg);
        if (value == -1) return -1;
        buffer[i] = value;
    }

    // Read pressure data (3 bytes)
    for (int i = 0; i < 3; i++) {
        int reg = BME280_REG_PRESSURE_MSB + i;
        uint8_t value = bme280_read_register(fd, reg);
        if (value == -1) return -1;
        buffer[3 + i] = value;
    }

    // Read humidity data (2 bytes)
    for (int i = 0; i < 2; i++) {
        int reg = BME280_REG_HUMIDITY_MSB + i;
        uint8_t value = bme280_read_register(fd, reg);
        if (value == -1) return -1;
        buffer[6 + i] = value;
    }

    // Combine bytes to form raw values
    *raw_temp = (int32_t)((((uint32_t)buffer[0]) << 12) | (((uint32_t)buffer[1]) << 4) | ((uint32_t)buffer[2] >> 4));
    *raw_pressure = (int32_t)((((uint32_t)buffer[3]) << 12) | (((uint32_t)buffer[4]) << 4) | ((uint32_t)buffer[5] >> 4));
    *raw_humidity = (int32_t)(((uint32_t)buffer[6] << 8) | ((uint32_t)buffer[7]));

    return 0;
}

// Function to compensate temperature data
float bme280_compensate_temperature(int32_t raw_temp, uint16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    int32_t var1, var2, T;
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    *t_fine = var1 + var2;
    T = (*t_fine * 5 + 128) >> 8;
    return (float)T / 100.0f;
}

// Function to compensate pressure data
float bme280_compensate_pressure(int32_t raw_pressure, uint16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576 - raw_pressure;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (float)p / 256.0f;
}

// Function to compensate humidity data
float bme280_compensate_humidity(int32_t raw_humidity, uint8_t dig_H1, int16_t dig_H2, uint8_t dig_H3, int16_t dig_H4, int16_t dig_H5, uint8_t dig_H6, int32_t t_fine) {
    int32_t v_x1_u32r;
    v_x1_u32r = (t_fine - ((int32_t)76800));
    v_x1_u32r = (((((raw_humidity << 14) - (((int32_t)dig_H4) << 20) - (((int32_t)dig_H5) * v_x1_u32r)) + ((int32_t)16384)) >> 15) * (((((((v_x1_u32r * ((int32_t)dig_H6)) >> 10) * (((v_x1_u32r * ((int32_t)dig_H3)) >> 11) + ((int32_t)32768))) >> 10) + ((int32_t)2097152)) * ((int32_t)dig_H2) + 8192) >> 14));
    v_x1_u32r = (v_x1_u32r - (((((v_x1_u32r >> 15) * (v_x1_u32r >> 15)) >> 7) * ((int32_t)dig_H1)) >> 4));
    v_x1_u32r = (v_x1_u32r < 0) ? 0 : v_x1_u32r;
    v_x1_u32r = (v_x1_u32r > 419430400) ? 419430400 : v_x1_u32r;
    float h = (v_x1_u32r >> 12);
    return h / 1024.0f;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the BME280 is present by reading the ID register
    int chip_id = bme280_read_register(i2c_fd, BME280_REG_ID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: BME280 not found. Chip ID: 0x%X\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    uint16_t dig_T1;
    int16_t dig_T2, dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    uint8_t dig_H1, dig_H3, dig_H6;
    int16_t dig_H2, dig_H4, dig_H5;
    if (bme280_read_calibration_data(i2c_fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9, &dig_H1, &dig_H2, &dig_H3, &dig_H4, &dig_H5, &dig_H6) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Set humidity control register
    if (bme280_write_register(i2c_fd, BME280_REG_CTRL_HUMIDITY, 0x01) != 0) {
        fprintf(stderr, "Error writing to humidity control register\n");
        close(i2c_fd);
        return 1;
    }

    // Set control measurement register
    if (bme280_write_register(i2c_fd, BME280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing to control measurement register\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temp, raw_pressure, raw_humidity;
        int32_t t_fine;

        // Read raw data
        if (bme280_read_raw_data(i2c_fd, &raw_temp, &raw_pressure, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            close(i2c_fd);
            return 1;
        }

        // Compensate data
        float temperature = bme280_compensate_temperature(raw_temp, dig_T1, dig_T2, dig_T3, &t_fine);
        float pressure = bme280_compensate_pressure(raw_pressure, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9, t_fine);
        float humidity = bme280_compensate_humidity(raw_humidity, dig_H1, dig_H2, dig_H3, dig_H4, dig_H5, dig_H6, t_fine);

        // Print data
        printf("Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0080  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single-ended AIN0, 128 SPS, +/-4.096V
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

        // Write configuration to ADS1115
        if (i2c_write_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error writing configuration to ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t conversion;
        if (i2c_read_word(i2c_fd, ADS1115_REG_CONVERT, &conversion) < 0) {
            fprintf(stderr, "Error reading conversion result from ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Print the raw ADC value
        printf("Raw ADC Value: %d\n", conversion);

        // Wait 200ms
        usleep(200000);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int running = 1;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    int ret;
    struct gpiod_line_request_config config;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        ret = gpiod_line_set_value(line, GPIO_VALUE);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);
        sleep(60);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z;

        if (read_accelerometer_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        usleep(10000); // 10ms delay
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    /* Request GPIO line for output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output_example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return 1;
    }

    /* Main loop */
    while (1) {
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            perror("Error setting GPIO value");
            cleanup();
            return 1;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);
        current_state = !current_state; /* Toggle state */
        usleep(50000); /* 0.05 seconds */
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the I2C address of the HD44780 controller
#define HD44780_I2C_ADDR 0x27

// Define the LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define LCD command constants
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// Define flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Define flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Define flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to write a command to the HD44780
int lcd_command(int fd, uint8_t cmd) {
    uint8_t data_u, data_l;
	uint8_t data_t[4];
	data_u = (cmd&0xF0);
	data_l = ((cmd<<4)&0xF0);
	data_t[0] = data_u|0x0C;  //en=1, rs=0
	data_t[1] = data_u|0x08;  //en=0, rs=0
	data_t[2] = data_l|0x0C;  //en=1, rs=0
	data_t[3] = data_l|0x08;  //en=0, rs=0
    if (write(fd, data_t, 4) != 4) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to write data to the HD44780
int lcd_data(int fd, uint8_t data) {
    uint8_t data_u, data_l;
	uint8_t data_t[4];
	data_u = (data&0xF0);
	data_l = ((data<<4)&0xF0);
	data_t[0] = data_u|0x0D;  //en=1, rs=1
	data_t[1] = data_u|0x09;  //en=0, rs=1
	data_t[2] = data_l|0x0D;  //en=1, rs=1
	data_t[3] = data_l|0x09;  //en=0, rs=1
    if (write(fd, data_t, 4) != 4) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the HD44780
int lcd_init(int fd) {
    // Initialize the LCD in 4-bit mode
    usleep(50000); // Wait for more than 40 ms after VCC rises to 4.5V
    if (lcd_command(fd, 0x33) != 0) return -1; // Initialize
    usleep(1000); // Wait for more than 4.1 ms
    if (lcd_command(fd, 0x32) != 0) return -1; // Initialize
    usleep(1000); // Wait for more than 100 us
    if (lcd_command(fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) != 0) return -1;
    usleep(1000); // Wait for more than 100 us
    if (lcd_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) != 0) return -1;
    usleep(1000); // Wait for more than 100 us
    if (lcd_command(fd, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT) != 0) return -1;
    usleep(1000); // Wait for more than 100 us
    if (lcd_command(fd, LCD_CLEARDISPLAY) != 0) return -1;
    usleep(2000); // Wait for more than 1.53 ms
    return 0;
}

// Function to clear the LCD display
int lcd_clear(int fd) {
    return lcd_command(fd, LCD_CLEARDISPLAY);
}

// Function to set the cursor position
int lcd_set_cursor(int fd, int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    return lcd_command(fd, LCD_SETDDRAMADDR | (col + row_offsets[row]));
}

// Function to print a string to the LCD
int lcd_print(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_data(fd, str[i]) != 0) return -1;
    }
    return 0;
}

int main() {
    int fd;
    char buffer[20];
    time_t rawtime;
    struct tm *timeinfo;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the I2C slave device
    if (ioctl(fd, I2C_SLAVE, HD44780_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Initialize the LCD
    if (lcd_init(fd) != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Get the current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format the time as a string
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Clear the LCD display
        lcd_clear(fd);

        // Set the cursor to the beginning of the first line
        lcd_set_cursor(fd, 0, 0);

        // Print the current time to the LCD
        lcd_print(fd, buffer);

        // Wait for 10 seconds
        sleep(10);
    }

    // Clear the LCD display before exiting
    lcd_clear(fd);

    // Close the I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

int i2c_fd;

void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    int i;
    int16_t accel_x, accel_y, accel_z;
    char buf[14];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Read 14 bytes of data (2 bytes per axis * 3 axes + 2 bytes for temperature)
    for (i = 0; i < 100; i++) {
        if (read(i2c_fd, buf, 14) != 14) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes for each axis
        accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        // Print the readings
        printf("Reading %d: Accel X: %d, Accel Y: %d, Accel Z: %d\n", i + 1, accel_x, accel_y, accel_z);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_14 14
#define GPIO_15 15

static struct gpiod_chip *chip;
static struct gpiod_line *line14, *line15;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", gpio);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static int read_gpio(int gpio, struct gpiod_line *line)
{
    int value, ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not read value from line %d\n", gpio);
        return -1;
    }

    value = ret;

    return value;
}

static int write_gpio(int gpio, struct gpiod_line *line, int value)
{
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value %d on line %d\n", value, gpio);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

int main()
{
    int value14, value15;
    time_t now;

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    /* Setup GPIO lines */
    if (setup_gpio(GPIO_14, &line14) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(GPIO_15, &line15) < 0) {
        cleanup_gpio(line14);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Read GPIO values */
        value14 = read_gpio(GPIO_14, line14);
        value15 = read_gpio(GPIO_15, line15);

        if (value14 < 0 || value15 < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values\n");
            break;
        }

        /* Validate GPIO values */
        if (value14 != 0 && value14 != 1) {
            fprintf(stderr, "Error: Invalid value %d read from GPIO %d\n", value14, GPIO_14);
            break;
        }
        if (value15 != 0 && value15 != 1) {
            fprintf(stderr, "Error: Invalid value %d read from GPIO %d\n", value15, GPIO_15);
            break;
        }

        /* Print GPIO values */
        now = time(NULL);
        printf("%ld: GPIO %d: %d, GPIO %d: %d\n", now, GPIO_14, value14, GPIO_15, value15);

        /* Wait for 5 seconds */
        sleep(5);
    }

    /* Cleanup GPIO lines */
    cleanup_gpio(line14);
    cleanup_gpio(line15);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "agriculture/sensor_data"
#define GPIO_PIN 4 // Example GPIO pin for sensor reading
#define VALID_MIN 0
#define VALID_MAX 1000

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor();
int validate_reading(int reading);
int publish_mqtt(int reading);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// Function to read sensor data from GPIO
int read_sensor() {
    int reading = gpioRead(GPIO_PIN);
    return reading;
}

// Function to validate sensor reading
int validate_reading(int reading) {
    if (reading >= VALID_MIN && reading <= VALID_MAX) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Function to publish data to MQTT broker
int publish_mqtt(int reading) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%d", reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return 1; // Error
    }
    return 0; // Success
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor data
        int sensor_reading = read_sensor();

        // Validate reading
        if (validate_reading(sensor_reading)) {
            // Publish to MQTT
            if (publish_mqtt(sensor_reading) != 0) {
                fprintf(stderr, "Error publishing MQTT message.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor reading: %d\n", sensor_reading);
        }

        // Sleep for 0.01 seconds
        usleep(10000); // 10000 microseconds = 0.01 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

