#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define LED_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 2.0      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
int validate_distance(float distance);
void control_led(int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        goto cleanup_chip;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        goto cleanup_trigger;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        goto cleanup_echo;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        goto cleanup_led;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        goto cleanup_trigger_req;
    }

    if (gpiod_line_request_output(led_line, "hc-sr04", 0) < 0) {
        perror("Error requesting LED line as output");
        goto cleanup_echo_req;
    }

    return 0;

cleanup_echo_req:
    gpiod_line_release(echo_line);
cleanup_trigger_req:
    gpiod_line_release(trigger_line);
cleanup_led:
    gpiod_line_release(led_line);
cleanup_echo:
    gpiod_line_release(echo_line);
cleanup_trigger:
    gpiod_line_release(trigger_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Trigger the HC-SR04 sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo line
long measure_pulse_width(void) {
    struct gpiod_line_event event;
    int ret;
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo line to go high
    ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for echo high");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo line to go low
    ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for echo low");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Validate the distance reading
int validate_distance(float distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Control the LED
void control_led(int state) {
    gpiod_line_set_value(led_line, state);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Distance Sensor Program\n");

    while (!terminate) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width. Retrying.\n");
            continue;
        }

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Validate the distance
        if (validate_distance(distance)) {
            printf("Distance: %.2f cm\n", distance);
            control_led(1); // Turn LED on
            usleep(100000);  // Wait 0.1 seconds
            control_led(0); // Turn LED off
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        usleep(100000); // Wait 0.1 seconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "myapp", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second
    struct timespec remaining_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);
        nanosleep(&sleep_time, &remaining_time);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);
        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

