// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensors/reading"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define MQTT_KEEP_ALIVE 60

// Global variables
static volatile int running = 1;
static MQTTClient client;
static char client_id[50];

// Function prototypes
int read_mcp3008(int channel);
int publish_mqtt(MQTTClient client, const char *topic, const char *payload);
void signal_handler(int sig);
int connect_mqtt(MQTTClient *client, const char *client_id, const char *broker_address, int port, int keep_alive);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to publish data to MQTT broker
int publish_mqtt(MQTTClient client, const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    if ((rc = MQTTClient_waitForCompletion(client, token, 1000)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for publish completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

// Function to connect to MQTT broker
int connect_mqtt(MQTTClient *client, const char *client_id, const char *broker_address, int port, int keep_alive) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    conn_opts.keepAliveInterval = keep_alive;
    conn_opts.cleansession = 1;
    conn_opts.username = NULL;
    conn_opts.password = NULL;

    if ((rc = MQTTClient_connect(*client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main() {
    int adc_value;
    char payload[50];
    int rc;

    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed!\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create MQTT client ID
    snprintf(client_id, sizeof(client_id), "%s_%ld", MQTT_CLIENT_ID, time(NULL));

    // Create MQTT client
    MQTTClient_create(&client, MQTT_BROKER, client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    // Connect to MQTT broker
    if (connect_mqtt(&client, client_id, MQTT_BROKER, MQTT_PORT, MQTT_KEEP_ALIVE) != 0) {
        MQTTClient_destroy(&client);
        return 1;
    }

    // Main loop
    while (running) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value!\n");
            continue; // Skip to the next iteration
        }

        // Format payload
        snprintf(payload, sizeof(payload), "%d", adc_value);

        // Publish to MQTT broker
        if (publish_mqtt(client, MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Failed to publish MQTT message!\n");
        }

        printf("Published: %s\n", payload);

        // Wait for a short period
        sleep(1);
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
