#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set trigger pin as output
    if (gpiod_line_request_output(trigger_line, "hc-sr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set echo pin as input
    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
        pulse_width++;
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
        pulse_width++;
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Distance Sensor\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            // Calculate the distance
            double distance = calculate_distance(pulse_width);

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse width\n");
        }

        // Wait for 200ms
        usleep(200000); // 200ms = 200000 us
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

