// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define MQTT_BROKER "tcp://localhost:1883" // Replace with your broker address
#define MQTT_TOPIC "home/entry/sensor/ads1115"
#define MQTT_CLIENT_ID "ads1115_client"
#define MQTT_KEEP_ALIVE 60
#define NUM_READINGS 10

// Global variables
int i2c_handle;
MQTTClient client;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t adc_value;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int16_t read_adc(int i2c_handle);
int publish_mqtt(sensor_data_t data);
void signal_handler(int signal);
int init_mqtt();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc(int i2c_handle) {
    char config[3];
    char buffer[2];
    int16_t adc_value;

    // Configure for single-ended A0, 4.096V, continuous conversion, 128 SPS
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (buffer[0] << 8) | buffer[1];
    return adc_value;
}

// Initialize MQTT client
int init_mqtt() {
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }
    return 0;
}

// Publish sensor data to MQTT broker
int publish_mqtt(sensor_data_t data) {
    char payload[100];
    struct tm *tm_info;
    char time_str[30];

    tm_info = localtime(&data.timestamp);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"adc_value\": %d}", time_str, data.adc_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    MQTTClient_waitForCompletion(client, token, 1000); // Wait for delivery
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor readings...\n");

    for (int i = 0; i < NUM_READINGS; i++) {
        // Read ADC value
        int16_t adc_value = read_adc(i2c_handle);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value, exiting\n");
            break;
        }

        // Get timestamp
        time_t now = time(NULL);

        // Create sensor data
        sensor_data_t data = {adc_value, now};

        // Publish to MQTT
        if (publish_mqtt(data) != 0) {
            fprintf(stderr, "Error publishing to MQTT, exiting\n");
            break;
        }

        printf("Published: ADC Value = %d\n", adc_value);

        // Wait 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

