}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 0);
