#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", GPIO_VALUE) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    signal(SIGINT, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

    while (!terminate) {
        if (gpiod_line_set_value(line, GPIO_VALUE) < 0) {
            perror("gpiod_line_set_value");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        nanosleep(&sleep_time, NULL);

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        nanosleep(&sleep_time, NULL);
    }

    printf("Exiting cleanly\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

