    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO 17 line */
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO17)");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Get GPIO 23 line */
    line23 = gpiod_chip_get_line(chip, GPIO23);
    if (!line23) {
        perror("gpiod_chip_get_line (GPIO23)");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO 17 as output */
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO17)");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO 23 as output */
    ret = gpiod_line_request(line23, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO23)");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set GPIO 17 high */
    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value (GPIO17)");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set GPIO 23 low */
    ret = gpiod_line_set_value(line23, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value (GPIO23)");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 17: HIGH, GPIO 23: LOW\n");

    /* Keep the program running until a signal is received */
    while (running) {
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 22

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request the GPIO line for output
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup();
        return 1;
    }

    // Main loop to toggle the GPIO state
    while (1) {
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            perror("Error setting GPIO value");
            cleanup();
            return 1;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);
        current_state = !current_state;
        sleep(1); // Wait for 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    serial_fd = setup_serial(UART_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    fprintf(stderr, "Reading from serial port %s at %d baud. Press Ctrl+C to exit.\n", UART_PORT, BAUD_RATE);

    while (program_running) {
        bytes_read = read(serial_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("%s", buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                // No data available or interrupted by signal, try again
                continue;
            } else {
                perror("Error reading from serial port");
                break;
            }
        } else {
            // No data read, but no error occurred (e.g., timeout)
            usleep(10000); // Sleep for 10ms to avoid busy-waiting
        }
    }

    if (serial_fd != -1) {
        close(serial_fd);
    }

    fprintf(stderr, "Program finished.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z;

        if (read_accelerometer_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

