// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3, uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3, int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6, int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    *dig_T1 = (uint16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00); 
    *dig_T1 |= ((uint16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 1)) << 8;

    *dig_T2 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 2);
    *dig_T2 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 3)) << 8;

    *dig_T3 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 4);
    *dig_T3 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 5)) << 8;

    *dig_P1 = (uint16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 6);
    *dig_P1 |= ((uint16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 7)) << 8;

    *dig_P2 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 8);
    *dig_P2 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 9)) << 8;

    *dig_P3 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 10);
    *dig_P3 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 11)) << 8;

    *dig_P4 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 12);
    *dig_P4 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 13)) << 8;

    *dig_P5 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 14);
    *dig_P5 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 15)) << 8;

    *dig_P6 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 16);
    *dig_P6 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 17)) << 8;

    *dig_P7 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 18);
    *dig_P7 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 19)) << 8;

    *dig_P8 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 20);
    *dig_P8 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 21)) << 8;

    *dig_P9 = (int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 22);
    *dig_P9 |= ((int16_t)i2c_read_reg(fd, BMP280_REG_CALIB_00 + 23)) << 8;

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int read_raw_data(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];

    // Read pressure data (3 bytes)
    data[0] = i2c_read_reg(fd, BMP280_REG_PRESS_MSB);
    data[1] = i2c_read_reg(fd, BMP280_REG_PRESS_LSB);
    data[2] = i2c_read_reg(fd, BMP280_REG_PRESS_XLSB);

    // Read temperature data (3 bytes)
    data[3] = i2c_read_reg(fd, BMP280_REG_TEMP_MSB);
    data[4] = i2c_read_reg(fd, BMP280_REG_TEMP_LSB);
    data[5] = i2c_read_reg(fd, BMP280_REG_TEMP_XLSB);

    if (data[0] == -1 || data[1] == -1 || data[2] == -1 || data[3] == -1 || data[4] == -1 || data[5] == -1) {
        return -1; // Indicate error
    }

    *raw_press = (int32_t)((((uint32_t)data[0]) << 12) | (((uint32_t)data[1]) << 4) | (((uint32_t)data[2]) >> 4));
    *raw_temp = (int32_t)((((uint32_t)data[3]) << 12) | (((uint32_t)data[4]) << 4) | (((uint32_t)data[5]) >> 4));

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temp, uint16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    double var1, var2, T;
    var1 = (((double)raw_temp) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temp) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temp) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    *t_fine = (int32_t)(var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_press, uint16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9, int32_t t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;
    return p;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the device is present by reading the ID register
    int chip_id = i2c_read_reg(i2c_fd, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: BMP280 not found. Chip ID: 0x%X\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    uint16_t dig_T1;
    int16_t dig_T2, dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (read_calibration_data(i2c_fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Set the BMP280 to forced mode
    if (i2c_write_reg(i2c_fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, forced mode
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temp, raw_press, t_fine;

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temp, &raw_press) == 0) {
            // Compensate temperature and pressure
            double temperature = compensate_temperature(raw_temp, dig_T1, dig_T2, dig_T3, &t_fine);
            double pressure = compensate_pressure(raw_press, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9, t_fine);

            // Print the results
            printf("Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading raw data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, result;
    FILE *fp;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Open file for writing
    fp = fopen("pwm_output.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        gpioTerminate();
        return 1;
    }

    // Generate PWM values and write to file
    for (i = 0; i <= PWM_RANGE; i++) {
        gpioPWM(GPIO_PIN, i);
        fprintf(fp, "%d\n", i);
        fflush(fp); // Ensure data is written to file immediately
        if (terminate) break; // Check for termination signal
        usleep(10000); // Delay for 10ms
    }

    // Close file
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    printf("PWM output complete. Data written to pwm_output.txt\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO5 5
#define GPIO6 6
#define GPIO13 13

static struct gpiod_chip *chip;
static struct gpiod_line *line5, *line6, *line13;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static void cleanup(void)
{
    if (line5) {
        gpiod_line_set_value(line5, 0);
        gpiod_line_release(line5);
    }
    if (line6) {
        gpiod_line_set_value(line6, 0);
        gpiod_line_release(line6);
    }
    if (line13) {
        gpiod_line_set_value(line13, 0);
        gpiod_line_release(line13);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get GPIO lines */
    line5 = gpiod_chip_get_line(chip, GPIO5);
    if (!line5) {
        perror("gpiod_chip_get_line (GPIO5)");
        cleanup();
        return EXIT_FAILURE;
    }

    line6 = gpiod_chip_get_line(chip, GPIO6);
    if (!line6) {
        perror("gpiod_chip_get_line (GPIO6)");
        cleanup();
        return EXIT_FAILURE;
    }

    line13 = gpiod_chip_get_line(chip, GPIO13);
    if (!line13) {
        perror("gpiod_chip_get_line (GPIO13)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request lines as outputs */
    ret = gpiod_line_request_output_flags(line5, "myprogram", 0, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output_flags (GPIO5)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output_flags(line6, "myprogram", 0, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output_flags (GPIO6)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output_flags(line13, "myprogram", 0, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output_flags (GPIO13)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Set initial values */
    ret = gpiod_line_set_value(line5, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value (GPIO5)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line6, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value (GPIO6)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line13, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value (GPIO13)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("GPIO5: %d, GPIO6: %d, GPIO13: %d\n", gpiod_line_get_value(line5), gpiod_line_get_value(line6), gpiod_line_get_value(line13));

    /* Wait for Ctrl+C */
    while (!terminate) {
        sleep(1);
    }

    /* Cleanup and exit */
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "agriculture/sensor_data"
#define GPIO_PIN 4 // Example GPIO pin for sensor data
#define SENSOR_ID "RPi_Node1" // Unique identifier for the node

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor_data();
int publish_data(int sensor_value);
void signal_handler(int signum);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting gracefully...\n", signum);
        running = 0;
    }
}

// Callback function for when the client connects to the broker
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Connection error: %s\n", mosquitto_connack_string(result));
        running = 0; // Exit if connection fails
    }
}

// Callback function for when the client disconnects from the broker
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        fprintf(stderr, "Disconnected unexpectedly with code %d\n", rc);
    }
    running = 0; // Exit the main loop
}

// Function to read sensor data from the GPIO pin
int read_sensor_data() {
    return gpioRead(GPIO_PIN);
}

// Function to publish sensor data to the MQTT broker
int publish_data(int sensor_value) {
    char payload[50];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    snprintf(payload, sizeof(payload), "{\"sensor_id\": \"%s\", \"timestamp\": \"%s\", \"value\": %d}", SENSOR_ID, timestamp, sensor_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return 1; // Indicate failure
    }

    printf("Published: %s\n", payload);
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor data
        int sensor_value = read_sensor_data();

        // Publish data
        if (publish_data(sensor_value) != 0) {
            fprintf(stderr, "Failed to publish data, exiting...\n");
            running = 0;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Disconnect from the MQTT broker
    mosquitto_disconnect(mosq);

    // Destroy the MQTT client instance
    mosquitto_destroy(mosq);

    // Cleanup libmosquitto
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

