#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // Assuming YUYV format

static int fd = -1;
static unsigned char *buffer = NULL;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    FILE *fp;
    char filename[20];
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Capture loop
    while (!stop) {
        // Dequeue buffer
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Save image
        snprintf(filename, sizeof(filename), "image_%d.yuv", time(NULL));
        fp = fopen(filename, "wb");
        if (fp == NULL) {
            perror("Error opening file");
            break;
        }
        fwrite(buffer, 1, buf.bytesused, fp);
        fclose(fp);

        printf("Captured image: %s\n", filename);

        // Requeue buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }

        sleep(1);
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
    }

    // Unmap buffer
    if (buffer != NULL) {
        if (munmap(buffer, buf.length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // Close device
    if (fd >= 0) {
        close(fd);
    }

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // Assuming YUYV format

static int fd = -1;
static unsigned char *buffer = NULL;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    FILE *fp;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming.\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuv", timeinfo);

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, IMAGE_SIZE, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    munmap(buffer, buf.length);
    close(fd);

    printf("Captured image saved to %s\n", filename);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3

static struct gpiod_chip *chip;
static struct gpiod_line *line2, *line3;

static void cleanup(void)
{
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int value;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO 2 line */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Error getting GPIO 2 line");
        cleanup();
        return 1;
    }

    /* Get GPIO 3 line */
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Error getting GPIO 3 line");
        cleanup();
        return 1;
    }

    /* Request GPIO 2 as output */
    config.consumer = "gpio2_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 2 as output");
        cleanup();
        return 1;
    }

    /* Request GPIO 3 as output */
    config.consumer = "gpio3_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line3, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 3 as output");
        cleanup();
        return 1;
    }

    /* Main loop */
    while (1) {
        /* Set GPIO 2 high */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 high");
            cleanup();
            return 1;
        }
        printf("GPIO 2: HIGH\n");

        /* Set GPIO 3 low */
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 low");
            cleanup();
            return 1;
        }
        printf("GPIO 3: LOW\n");

        /* Wait 0.5 seconds */
        sleep(1);

        /* Set GPIO 2 low */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 low");
            cleanup();
            return 1;
        }
        printf("GPIO 2: LOW\n");

        /* Set GPIO 3 high */
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 high");
            cleanup();
            return 1;
        }
        printf("GPIO 3: HIGH\n");

        /* Wait 0.5 seconds */
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line27;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO17)");
        goto close_chip;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        perror("gpiod_chip_get_line (GPIO27)");
        goto close_line17;
    }

    ret = gpiod_line_request_output(line17, "myapp", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        goto close_line27;
    }

    ret = gpiod_line_request_output(line27, "myapp", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO27)");
        goto release_line17;
    }

    return 0;

release_line17:
    gpiod_line_release(line17);
close_line27:
    gpiod_line_release(line27);
close_line17:
    gpiod_line_release(line17);
close_chip:
    gpiod_chip_close(chip);
    return -1;
}

static void cleanup_gpio(void)
{
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {1, 0}; // 1 second
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break;
        }
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO27)");
            break;
        }

        printf("GPIO17=0, GPIO27=1\n");

        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break;
        }
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO27)");
            break;
        }

        printf("GPIO17=1, GPIO27=0\n");

        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();

    printf("Exiting cleanly\n");
    return EXIT_SUCCESS;
}

