#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY 'N' // 'N' for None, 'O' for Odd, 'E' for Even

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

void cleanup() {
    if (serial_fd != -1) {
        close(serial_fd);
        fprintf(stderr, "Serial port closed.\n");
    }
}

int main() {
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open serial port
    serial_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }
    fprintf(stderr, "Serial port opened successfully.\n");

    // Configure serial port
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        cleanup();
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // Set baud rate, 8 data bits, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0; // Raw output
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0; // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Serial port configured.\n");

    // Main loop
    while (program_running) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Received: %s", timestamp, buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                // No data available or interrupted by signal, continue
                continue;
            } else {
                perror("Error reading from serial port");
                break;
            }
        } else {
            // No data read, but no error occurred (e.g., timeout)
            // Optionally, add a small delay to avoid busy-waiting
            usleep(10000); // 10ms
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO18 18
#define GPIO23 23
#define GPIO24 24

static struct gpiod_chip *chip;
static struct gpiod_line *line18, *line23, *line24;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

static int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO18, &line18) < 0 ||
        setup_gpio(GPIO23, &line23) < 0 ||
        setup_gpio(GPIO24, &line24) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = set_gpio_value(line18, 1);
    if (ret < 0) goto cleanup;
    ret = set_gpio_value(line23, 0);
    if (ret < 0) goto cleanup;
    ret = set_gpio_value(line24, 1);
    if (ret < 0) goto cleanup;

    printf("GPIO 18: %d, GPIO 23: %d, GPIO 24: %d\n", gpiod_line_get_value(line18), gpiod_line_get_value(line23), gpiod_line_get_value(line24));

cleanup:
    cleanup_gpio(line18);
    cleanup_gpio(line23);
    cleanup_gpio(line24);
    gpiod_chip_close(chip);

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
