        dutyCycle += 50;
        if (dutyCycle > 255) {
            dutyCycle = 0;
        }
        sleep(1);
    }

    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

