#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_lengths[80];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 to match DHT22 datasheet

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal.\n");
        return -1;
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for end of start signal.\n");
        return -1;
    }

    // Read the 40 bits of data
    for (i = 0; i < 80; i++) {
        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit start.\n");
            return -1;
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit end.\n");
            return -1;
        }
        long end = gpioTick();
        pulse_lengths[i] = end - start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if (pulse_lengths[i] > 40) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    // Validate the checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22: Checksum error.\n");
        return -1;
    }

    // Convert the data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht22_data(DHT22_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data.\n");
        }

        sleep(5);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

