#include <MQTTClient.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MQTT_BROKER "localhost" // Change to your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/entry/sensor1"
#define MQTT_CLIENT_ID "rpi_sensor1"
#define MQTT_KEEP_ALIVE 60

// Global variables
int spi_handle;
MQTTClient client;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int publish_mqtt(int reading);
void signal_handler(int sig);
int connect_mqtt();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to publish data to MQTT broker
int publish_mqtt(int reading) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[32];

    snprintf(payload, sizeof(payload), "%d", reading);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    MQTTClient_waitForCompletion(client, token, MQTT_KEEP_ALIVE);

    printf("Published: %s\n", payload);
    return 0;
}

// Function to connect to MQTT broker
int connect_mqtt() {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }

    printf("Connected to MQTT broker\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT client
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (connect_mqtt() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int reading = read_mcp3008(0);
        if (reading >= 0) {
            publish_mqtt(reading);
        } else {
            fprintf(stderr, "Failed to read MCP3008\n");
        }

        sleep(5);
    }

    // Cleanup
    MQTTClient_disconnect(client, MQTT_KEEP_ALIVE);
    MQTTClient_destroy(&client);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exited cleanly\n");
    return 0;
}

#include <stdio.h>
