static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 100000000; // 100ms

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line17 || !line18) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request lines for output */
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO 17)");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(line18, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO 18)");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    for (int i = 0; i < 3 && !terminate; ++i) {
        /* Set GPIO 17 high */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            break;
        }
        printf("GPIO 17 set HIGH\n");
        nanosleep(&delay, NULL);

        /* Set GPIO 18 low */
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 18)");
            break;
        }
        printf("GPIO 18 set LOW\n");
        nanosleep(&delay, NULL);

        /* Set GPIO 17 low */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            break;
        }
        printf("GPIO 17 set LOW\n");
        nanosleep(&delay, NULL);

        /* Set GPIO 18 high */
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 18)");
            break;
        }
        printf("GPIO 18 set HIGH\n");
        nanosleep(&delay, NULL);
    }

    /* Release lines */
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    /* Close chip */
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return 0;
}

