#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// PCF8574 I2C address
#define PCF8574_ADDR 0x27

// PCF8574 pin definitions
#define PCF8574_PIN_A 0
#define PCF8574_PIN_B 1
#define PCF8574_PIN_C 2
#define PCF8574_PIN_D 3
#define PCF8574_PIN_E 4
#define PCF8574_PIN_F 5
#define PCF8574_PIN_G 6
#define PCF8574_PIN_DP 7

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    // Set all pins to low before exiting
    uint8_t data = 0x00;
    if (i2c_fd != -1) {
        if (write(i2c_fd, &data, 1) != 1) {
            perror("Failed to write to I2C device");
        }
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a value to the PCF8574
int write_pcf8574(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("PCF8574 test program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Generate a random value
        uint8_t value = rand() % 256;

        // Write the value to the PCF8574
        if (write_pcf8574(i2c_fd, value) != 0) {
            fprintf(stderr, "Error writing to PCF8574. Continuing...\n");
        }

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

