#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define NUM_GPIOS 5
const int gpios[NUM_GPIOS] = {4, 17, 22, 23, 24};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
int current_state = 0;

void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request lines for output
    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            cleanup(0);
            return 1;
        }

        config.consumer = "my_program";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for output");
            cleanup(0);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set GPIO states
        for (int i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], (current_state >> i) & 1);
            if (ret < 0) {
                perror("Error setting GPIO value");
                cleanup(0);
                return 1;
            }
        }

        // Print current state
        printf("Current state: %d\n", current_state);

        // Increment state
        current_state = (current_state + 1) % (1 << NUM_GPIOS);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

