static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, int value)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    line4 = gpiod_chip_get_line(chip, gpio);
    if (!line4) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(line4, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(line4);
        return -1;
    }

    ret = gpiod_line_set_value(line4, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line %d value: %s\n", gpio, strerror(errno));
        gpiod_line_release(line4);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line4) {
        gpiod_line_release(line4);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO4, 1) < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO17, 0) < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to 1, GPIO %d set to 0\n", GPIO4, GPIO17);

    while (!terminate) {
        sleep(1);
    }

    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

