        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO_11, &line_11) < 0) {
        cleanup_gpio(line_10);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = set_gpio_value(line_10, 1);
