    while (!terminate) {
        sleep(1);
    }

    printf("Cleaning up and exiting...\n");

    cleanup_gpio(line_10);
    cleanup_gpio(line_11);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

