// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void report_state(double distance);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger a 10us pulse on the trigger pin
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    struct timespec ts = {0, 10}; // 10 microseconds
    nanosleep(&ts, NULL);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo pin to go high
    int ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error reading echo line");
        return -1;
    }
    if (ret == 0) {
        return -1; // No echo detected
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Wait for the echo pin to go low or timeout
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error reading echo line");
            return -1;
        }
        if (ret == 0) {
            break;
        }

        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
            perror("clock_gettime");
            return -1;
        }

        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;

        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo\n");
            return -1; // Timeout
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("clock_gettime");
        return -1;
    }

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Report the distance to standard output
void report_state(double distance) {
    if (distance < 0) {
        printf("Error: No echo detected or timeout\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (!terminate) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();
        double distance = calculate_distance(pulse_width);
        report_state(distance);
        sleep(1);
    }

    // Cleanup and exit
    printf("Exiting cleanly.\n");
    cleanup_gpio();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_8  8  // BCM numbering
#define GPIO_9  9  // BCM numbering
#define GPIO_11 11 // BCM numbering
#define GPIO_18 18 // BCM numbering

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop PWM on all pins
    gpioPWM(GPIO_8, 0);
    gpioPWM(GPIO_9, 0);
    gpioPWM(GPIO_11, 0);
    gpioPWM(GPIO_18, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_11, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Main loop
    while (1) {
        // Generate PWM values (0-255)
        for (int i = 0; i <= 255; i++) {
            // Set PWM duty cycle
            gpioPWM(GPIO_8, i);
            gpioPWM(GPIO_9, i);
            gpioPWM(GPIO_11, i);
            gpioPWM(GPIO_18, i);

            // Print PWM values to standard output
            printf("GPIO 8: %d, GPIO 9: %d, GPIO 11: %d, GPIO 18: %d\n", i, i, i, i);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second = 1000000 microseconds
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // Assuming YUYV format

static int fd = -1;
static unsigned char *buffer = NULL;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Capture and save image
    while (!stop) {
        // Dequeue buffer
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Save image to file
        FILE *fp = fopen("capture.yuv", "wb");
        if (fp == NULL) {
            perror("Error opening file");
            break;
        }
        fwrite(buffer, 1, IMAGE_SIZE, fp);
        fclose(fp);

        printf("Captured image and saved to capture.yuv\n");

        // Requeue buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }

        // Wait 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&ts, NULL);
    }

    // Stop streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
    }

    // Unmap buffer
    if (buffer != NULL) {
        if (munmap(buffer, buf.length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // Close device
    if (fd != -1) {
        close(fd);
    }

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        for (i = 0; i <= PWM_RANGE; i++) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            sleep(1);
        }
        for (i = PWM_RANGE; i >= 0; i--) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            sleep(1);
        }
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

// Define the PCF8574 pins connected to the display segments (A-G)
#define SEG_A 0x01
#define SEG_B 0x02
#define SEG_C 0x04
#define SEG_D 0x08
#define SEG_E 0x10
#define SEG_F 0x20
#define SEG_G 0x40

// Define the PCF8574 pins connected to the display digits (1-4)
#define DIGIT_1 0x80
#define DIGIT_2 0x40
#define DIGIT_3 0x20
#define DIGIT_4 0x10

// Define the PCF8574 pins connected to the display control (enable, reset, etc.)
#define DISPLAY_ENABLE 0x08
#define DISPLAY_RESET 0x04

// Define the I2C file descriptor
int i2c_fd;

// Function prototypes
int i2c_write_byte(int fd, uint8_t data);
void display_digit(int digit, int value);
void display_number(int number);
void cleanup(int signal);

// Structure to hold the display state
typedef struct {
    uint8_t digit1;
    uint8_t digit2;
    uint8_t digit3;
    uint8_t digit4;
} display_state_t;

display_state_t current_state = {0, 0, 0, 0};

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to display a digit on the display
void display_digit(int digit, int value) {
    uint8_t data = 0x00; // Default to all segments off

    switch (value) {
        case 0: data = SEG_A | SEG_B | SEG_C | SEG_D | SEG_E | SEG_F; break;
        case 1: data = SEG_B | SEG_C; break;
        case 2: data = SEG_A | SEG_B | SEG_D | SEG_E | SEG_G; break;
        case 3: data = SEG_A | SEG_B | SEG_C | SEG_D | SEG_G; break;
        case 4: data = SEG_B | SEG_C | SEG_F | SEG_G; break;
        case 5: data = SEG_A | SEG_C | SEG_D | SEG_F | SEG_G; break;
        case 6: data = SEG_A | SEG_C | SEG_D | SEG_E | SEG_F | SEG_G; break;
        case 7: data = SEG_A | SEG_B | SEG_C; break;
        case 8: data = SEG_A | SEG_B | SEG_C | SEG_D | SEG_E | SEG_F | SEG_G; break;
        case 9: data = SEG_A | SEG_B | SEG_C | SEG_F | SEG_G; break;
        default: data = 0x00; break; // Turn off the digit if the value is invalid
    }

    uint8_t control_byte = 0x00; // Default to all digits off

    switch (digit) {
        case 1: control_byte = DIGIT_1; break;
        case 2: control_byte = DIGIT_2; break;
        case 3: control_byte = DIGIT_3; break;
        case 4: control_byte = DIGIT_4; break;
    }

    // Set the digit to be displayed
    if (i2c_write_byte(i2c_fd, control_byte) != 0) return;
    if (i2c_write_byte(i2c_fd, data) != 0) return;
    if (i2c_write_byte(i2c_fd, control_byte | DISPLAY_ENABLE) != 0) return; // Enable the digit
    usleep(1000); // Short delay to allow the display to update
    if (i2c_write_byte(i2c_fd, control_byte) != 0) return; // Disable the digit
}

// Function to display a number on the display
void display_number(int number) {
    int digits[4];
    digits[0] = (number / 1000) % 10; // Thousands
    digits[1] = (number / 100) % 10;  // Hundreds
    digits[2] = (number / 10) % 10;   // Tens
    digits[3] = number % 10;          // Ones

    display_digit(1, digits[0]);
    display_digit(2, digits[1]);
    display_digit(3, digits[2]);
    display_digit(4, digits[3]);
}

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");

    // Turn off all digits
    i2c_write_byte(i2c_fd, 0x00); // Disable all digits
    i2c_write_byte(i2c_fd, 0x00); // Turn off all segments

    // Reset the display (if needed, depends on your specific display module)
    // i2c_write_byte(i2c_fd, DISPLAY_RESET); // Reset the display

    close(i2c_fd);
    exit(0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the display (reset, enable, etc.)
    // This might vary depending on your specific display module
    i2c_write_byte(i2c_fd, DISPLAY_RESET); // Reset the display
    usleep(10000); // Wait for reset to complete
    i2c_write_byte(i2c_fd, 0x00); // Turn off all segments initially

    // Display a number
    display_number(1234);

    // Wait for a while
    sleep(5);

    // Clean up and exit
    cleanup(0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 16

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int current_state = 0;

static void cleanup(int signal)
{
    printf("\nCleaning up and exiting...\n");
    if (line) {
        gpiod_line_set_value(line, 0); // Set to low on exit
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    /* Install signal handler for Ctrl+C */
    signal(SIGINT, cleanup);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set initial state to low */
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting initial GPIO value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    current_state = 0;
    printf("Initial GPIO state: LOW\n");

    /* Toggle state every 1 second */
    while (1) {
        ret = gpiod_line_set_value(line, !current_state);
        if (ret < 0) {
            perror("Error setting GPIO value");
            cleanup(0);
            return 1;
        }
        current_state = !current_state;
        printf("GPIO state: %s\n", current_state ? "HIGH" : "LOW");
        sleep(1);
    }

    return 0;
}

