#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioPWM(GPIO_18, 128); // 50% duty cycle
        gpioPWM(GPIO_23, 192); // 75% duty cycle
        gpioPWM(GPIO_24, 255); // 100% duty cycle

        printf("GPIO 18: 50%%, GPIO 23: 75%%, GPIO 24: 100%%\n");
        gpioDelay(100000); // 0.1 seconds

        gpioPWM(GPIO_18, 64);  // 25% duty cycle
        gpioPWM(GPIO_23, 96);  // 48% duty cycle
        gpioPWM(GPIO_24, 127); // 76% duty cycle

        printf("GPIO 18: 25%%, GPIO 23: 48%%, GPIO 24: 76%%\n");
        gpioDelay(100000); // 0.1 seconds
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_received = 0;
static volatile unsigned int start_time = 0;
static volatile unsigned int end_time = 0;

// Function prototypes
int setup_gpio(void);
void trigger_pulse(void);
void echo_callback(int value, void *user_data);
double calculate_distance(unsigned int pulse_width);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
} gpio_line_t;

// Function to set up GPIO lines
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "hc-sr04", 0);
    if (ret < 0) {
        perror("Error requesting trigger line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line for input with rising edge detection
    ret = gpiod_line_request_rising_edge_events(echo_line, "hc-sr04");
    if (ret < 0) {
        perror("Error requesting echo line for rising edge events");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to send a trigger pulse
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Callback function for echo line events
void echo_callback(int value, void *user_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    unsigned int current_time = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    if (value == 1) {
        start_time = current_time;
        echo_received = 1; // Indicate rising edge
    } else if (value == 0 && echo_received) {
        end_time = current_time;
        echo_received = 2; // Indicate falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to clean up GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

int main(void) {
    int ret;
    struct gpiod_line_event_request_config config;
    struct gpiod_line_event event;
    unsigned int pulse_width;
    double distance;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Configure callback for echo line
    config.event_callback = echo_callback;
    config.user_data = NULL;

    ret = gpiod_line_event_request(echo_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting event callback");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        echo_received = 0; // Reset flag
        start_time = 0;
        end_time = 0;

        // Send trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = TIMEOUT_US * 1000; // Convert microseconds to nanoseconds
        ret = gpiod_line_event_wait(echo_line, &timeout);

        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "Timeout waiting for echo.\n");
                break; // Exit loop after timeout
            } else {
                perror("Error waiting for echo");
                break;
            }
        }

        // Calculate pulse width
        if (echo_received == 2) {
            pulse_width = end_time - start_time;
        } else {
            fprintf(stderr, "Incomplete echo signal received.\n");
            break;
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait before next measurement
        sleep(1);
    }

    // Clean up GPIO
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", GPIO_VALUE) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {5, 0}; // 5 seconds
    struct timespec remaining_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to %d every 5 seconds until interrupted.\n", GPIO_PIN, GPIO_VALUE);

    while (!terminate) {
        if (gpiod_line_set_value(line, GPIO_VALUE) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

        if (nanosleep(&sleep_time, &remaining_time) < 0) {
            if (errno == EINTR) {
                printf("Interrupted by signal. Exiting.\n");
                break;
            } else {
                perror("nanosleep");
                break;
            }
        }
    }

    cleanup_gpio();
    printf("GPIO %d released. Exiting.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = (i2c_read_reg(i2c_fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_XOUT_H + 1);
        int16_t accel_y = (i2c_read_reg(i2c_fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_YOUT_H + 1);
        int16_t accel_z = (i2c_read_reg(i2c_fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_ZOUT_H + 1);

        // Print accelerometer data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles in seconds
#define CYCLE_DELAY 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2, *line3, *line17;

// Function prototypes
int read_gpio(int gpio);
int validate_reading(int reading);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (line17) {
        gpiod_line_release(line17);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the state of a GPIO pin
int read_gpio(int gpio) {
    int value;

    // Get the current value of the GPIO pin
    value = gpiod_line_get_value(line2); // Use line2 for all GPIOs, as it's the common one
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1; // Indicate an error
    }

    return value;
}

// Function to validate the reading
int validate_reading(int reading) {
    // Check if the reading is 0 or 1
    if (reading == 0 || reading == 1) {
        return 1; // Valid reading
    } else {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Invalid reading
    }
}

int main() {
    int i, reading2, reading3, reading17;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line2 || !line3 || !line17) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup(0); // Call cleanup before exiting
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line2, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_2, strerror(errno));
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(line3, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_3, strerror(errno));
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(line17, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_17, strerror(errno));
        cleanup(0);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 2 to 1
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to 1: %s\n", GPIO_2, strerror(errno));
            cleanup(0);
            return 1;
        }
        // Set GPIO 3 to 0
        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to 0: %s\n", GPIO_3, strerror(errno));
            cleanup(0);
            return 1;
        }
        // Set GPIO 17 to 1
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to 1: %s\n", GPIO_17, strerror(errno));
            cleanup(0);
            return 1;
        }

        // Read GPIO 2
        reading2 = read_gpio(GPIO_2);
        if (reading2 < 0) {
            cleanup(0);
            return 1;
        }
        if (!validate_reading(reading2)) {
            cleanup(0);
            return 1;
        }

        // Read GPIO 3
        reading3 = read_gpio(GPIO_3);
        if (reading3 < 0) {
            cleanup(0);
            return 1;
        }
        if (!validate_reading(reading3)) {
            cleanup(0);
            return 1;
        }

        // Read GPIO 17
        reading17 = read_gpio(GPIO_17);
        if (reading17 < 0) {
            cleanup(0);
            return 1;
        }
        if (!validate_reading(reading17)) {
            cleanup(0);
            return 1;
        }

        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d, GPIO 17 = %d\n", i + 1, reading2, reading3, reading17);

        // Delay for 5 seconds
        sleep(CYCLE_DELAY);
    }

    // Clean up and exit
    cleanup(0);

    return 0;
}

