#include <errno.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// SHT31 commands
#define SHT31_MEASURE_CMD 0x2400 // High repeatability, clock stretching disabled

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Function to read data from SHT31
int read_sht31(int i2c_handle, sensor_data_t *data) {
    uint8_t cmd[2] = {(SHT31_MEASURE_CMD >> 8) & 0xFF, SHT31_MEASURE_CMD & 0xFF};
    uint8_t buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (typical 10ms, max 15ms)
    gpioDelay(20); // Wait 20ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert data
    uint16_t temperature_raw = (buffer[0] << 8) | buffer[1];
    uint16_t humidity_raw = (buffer[3] << 8) | buffer[4];

    // Checksum validation (not implemented for brevity)

    // Calculate temperature and humidity
    data->temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

