struct gpiod_line *lines[NUM_GPIOS];
int running = 1;

void cleanup() {
    printf("Cleaning up...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request lines for output
    for (int i = 0; i < NUM_GPIOS; i++) {
        config.consumer = "gpio_output";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpios[i], strerror(errno));
            cleanup();
            return 1;
        }

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", gpios[i], strerror(errno));
            cleanup();
            return 1;
        }
