            fprintf(stderr, "Error setting line %d to 1: %s\n", gpios[i], strerror(errno));
            cleanup();
            return 1;
        }
        printf("GPIO %d (BCM %d) set to 1\n", gpios[i], gpios[i]);
    }

    // Wait for a while
    sleep(1);

    // Set output values and print
    for (int i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting line %d to 0: %s\n", gpios[i], strerror(errno));
            cleanup();
            return 1;
        }
        printf("GPIO %d (BCM %d) set to 0\n", gpios[i], gpios[i]);
