#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM range
#define PWM_RANGE 1000

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency and range for each GPIO
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_17, PWM_RANGE);

    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);

    gpioSetPWMfrequency(GPIO_22, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_22, PWM_RANGE);

    gpioSetPWMfrequency(GPIO_27, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_27, PWM_RANGE);

    // Generate PWM signals with different duty cycles
    for (int duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 100) {
        gpioPWM(GPIO_17, duty_cycle);
        gpioPWM(GPIO_18, duty_cycle);
        gpioPWM(GPIO_22, duty_cycle);
        gpioPWM(GPIO_27, duty_cycle);

        printf("GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 27: %d\n", duty_cycle, duty_cycle, duty_cycle, duty_cycle);
        usleep(100000); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

