#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

struct gpiod_chip *chip;
struct gpiod_line *line2, *line3, *line17;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line2 || !line3 || !line17) {
        perror("Error getting GPIO line");
        ret = 1;
        goto cleanup;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line2, "myprogram", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line3, "myprogram", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3 for output");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line17, "myprogram", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        goto cleanup;
    }

    // Main loop
    for (int i = 0; i < 3 && program_running; ++i) {
        // Set GPIO states
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 value");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 value");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }

        // Print state
        printf("Cycle %d: GPIO 2=1, GPIO 3=0, GPIO 17=1\n", i + 1);

        // Wait
        nanosleep(&sleep_time, NULL);

        // Set GPIO states
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 value");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 value");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }

        // Print state
        printf("Cycle %d: GPIO 2=0, GPIO 3=1, GPIO 17=0\n", i + 1);

        // Wait
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line17) gpiod_line_release(line17);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return ret;
}

