#define DEVICE_NAME "/dev/video0" // Adjust if needed
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // Assuming YUYV format

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *image_buffer;
    FILE *output_file;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening video device");
        return 1;
    }

    // Check if the device is a video capture device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    image_buffer = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (image_buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Capture an image
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(image_buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting stream");
        munmap(image_buffer, buf.length);
        close(fd);
        return 1;
    }

    // Read the image
    if (read(fd, image_buffer, IMAGE_SIZE) != IMAGE_SIZE) {
        perror("Error reading image");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(image_buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping stream");
        munmap(image_buffer, buf.length);
        close(fd);
        return 1;
    }

    // Save the image to a file
    output_file = fopen("captured_image.yuv", "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        munmap(image_buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(image_buffer, 1, IMAGE_SIZE, output_file);
    fclose(output_file);

    // Clean up
    munmap(image_buffer, buf.length);
    close(fd);

    printf("Image captured and saved as captured_image.yuv\n");
    return 0;
}

