    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    struct timespec remaining_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);
        nanosleep(&sleep_time, &remaining_time);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);
        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup_gpio();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

