#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio18/value"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;
    FILE *fp;
    char value_str[2];
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    config.consumer = "gpio18_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value to 1");
            break;
        }

        fp = fopen(GPIO_VALUE_PATH, "r");
        if (!fp) {
            perror("Error opening GPIO value file");
            break;
        }

        if (fgets(value_str, sizeof(value_str), fp) == NULL) {
            perror("Error reading GPIO value");
            fclose(fp);
            break;
        }
        fclose(fp);

        if (value_str[0] != '1') {
            fprintf(stderr, "Invalid GPIO value: %s\n", value_str);
            continue;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        printf("GPIO 18 is HIGH at: %s", asctime(timeinfo));

        sleep(5);
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
