#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_PIN 4 // BCM numbering
#define GPIO_PATH "/sys/class/gpio/gpio4"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

int read_temperature(const char *device_id, float *temperature) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", filepath, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", filepath);
        return -1;
    }

    long temp_reading = strtol(temp_str + 2, NULL, 10);
    if (temp_reading == 0 && errno == EINVAL) {
        fprintf(stderr, "Error converting temperature from %s\n", filepath);
        return -1;
    }

    *temperature = (float)temp_reading / 1000.0;
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    // Export GPIO pin
    int export_fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (export_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        return 1;
    }
    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
    if (write(export_fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        close(export_fd);
        return 1;
    }
    close(export_fd);

    // Set GPIO direction to input
    int direction_fd = open(GPIO_DIRECTION_PATH, O_WRONLY);
    if (direction_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_DIRECTION_PATH, strerror(errno));
        goto unexport;
    }
    if (write(direction_fd, "in", 2) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_DIRECTION_PATH, strerror(errno));
        close(direction_fd);
        goto unexport;
    }
    close(direction_fd);

    // Find DS18B20 device ID
    char device_id[20] = {0};
    DIR *dir;
    struct dirent *ent;
    dir = opendir(W1_DEVICES_DIR);
    if (dir != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strstr(ent->d_name, "28-") != NULL) {
                strncpy(device_id, ent->d_name, sizeof(device_id) - 1);
                break;
            }
        }
        closedir(dir);
    } else {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        goto unexport;
    }

    if (device_id[0] == '\0') {
        fprintf(stderr, "DS18B20 device not found.\n");
        goto unexport;
    }

    printf("DS18B20 device ID: %s\n", device_id);

    for (int i = 0; i < 3 && program_running; ++i) {
        float temperature;
        if (read_temperature(device_id, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
            sleep(5);
            continue;
        }
        sleep(5);
    }

unexport:
    // Unexport GPIO pin
    int unexport_fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (unexport_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return 1;
    }
    if (write(unexport_fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        close(unexport_fd);
        return 1;
    }
    close(unexport_fd);

    return 0;
}

