#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
void set_led(int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set trigger pin as output
    if (gpiod_line_request_output(trigger_line, "hc-sr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set echo pin as input
    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set LED pin as output
    if (gpiod_line_request_output(led_line, "hc-sr04", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the HC-SR04 sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for echo to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        pulse_width++;
        usleep(1); // Check every microsecond
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        pulse_width++;
        usleep(1); // Check every microsecond
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Set the LED state
void set_led(int state) {
    gpiod_line_set_value(led_line, state);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor Program\n");

    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            // Calculate the distance
            float distance = calculate_distance(pulse_width);

            // Set the LED based on distance
            if (distance < 20.0) {
                set_led(1); // Turn LED on
            } else {
                set_led(0); // Turn LED off
            }

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: No echo received.\n");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
