#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define NUM_CYCLES 10

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int set_gpio_state(int state)
{
    if (gpiod_line_set_value(line, state) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void log_state(int state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s GPIO %d set to %d\n", timestamp, GPIO_PIN, state);
}

int main(void)
{
    int i;

    signal(SIGINT, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CYCLES; i++) {
        if (set_gpio_state(1) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        log_state(1);
        sleep(1);

        if (set_gpio_state(0) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        log_state(0);
        sleep(1);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

