#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO23 23
#define GPIO24 24

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line23, *line24;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

static int set_gpio_state(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(GPIO17, &line17) < 0 ||
        setup_gpio(GPIO23, &line23) < 0 ||
        setup_gpio(GPIO24, &line24) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = set_gpio_state(line17, 1);
    if (ret < 0) goto cleanup;

    ret = set_gpio_state(line23, 0);
    if (ret < 0) goto cleanup;

    ret = set_gpio_state(line24, 1);
    if (ret < 0) goto cleanup;

    printf("GPIO 17: %d, GPIO 23: %d, GPIO 24: %d\n", gpiod_line_get_value(line17), gpiod_line_get_value(line23), gpiod_line_get_value(line24));

cleanup:
    cleanup_gpio(line17);
    cleanup_gpio(line23);
    cleanup_gpio(line24);
    gpiod_chip_close(chip);

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Function prototypes
int read_sensor(int gpio);
int validate_reading(int reading);
void set_pwm(int gpio, int duty_cycle);
void cleanup(int signum);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void cleanup(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signum);
    gpioTerminate();
    exit(0);
}

// Function to read sensor value from a GPIO pin
int read_sensor(int gpio) {
    int reading = gpioRead(gpio);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, reading);
        return -1; // Indicate an error
    }
    return reading;
}

// Function to validate sensor reading
int validate_reading(int reading) {
    if (reading == 0 || reading == 1) {
        return 1; // Valid reading
    } else {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Invalid reading
    }
}

// Function to set PWM duty cycle on a GPIO pin
void set_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle: %d. Must be between 0 and %d\n", duty_cycle, PWM_RANGE);
        return;
    }
    gpioPWM(gpio, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_4, PWM_RANGE);
    gpioSetPWMrange(GPIO_17, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (program_running) {
        // Read sensor values
        int reading4 = read_sensor(GPIO_4);
        int reading17 = read_sensor(GPIO_17);
        int reading18 = read_sensor(GPIO_18);

        // Validate readings
        int valid4 = validate_reading(reading4);
        int valid17 = validate_reading(reading17);
        int valid18 = validate_reading(reading18);

        // Set PWM duty cycles based on readings
        if (valid4) {
            set_pwm(GPIO_4, reading4 * 128); // Scale 0/1 to 0/128
        }
        if (valid17) {
            set_pwm(GPIO_17, reading17 * 128);
        }
        if (valid18) {
            set_pwm(GPIO_18, reading18 * 128);
        }

        // Print sensor values
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d\n", reading4, reading17, reading18);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

