#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Wait for the DHT22 to pull the line low again
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Wait 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Wait 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        long pulse_length = end - start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if (pulse_length > 40) { // Changed from 50 to 40 to avoid false positives
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Check the checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1; // Checksum error
    }

    // Convert the data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int cycles = 3;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    while (cycles > 0 && !terminate) {
        if (read_dht22_data(DHT22_GPIO, &temperature, &humidity) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Temperature: %.1f°C, Humidity: %.1f%%\n", timestamp, temperature, humidity);
            cycles--;
        } else {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(stderr, "%s - Failed to read DHT22 data\n", timestamp);
            break; // Exit the loop if read fails
        }

        sleep(5);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

