        cleanup(0);
        return 1;
    }

    lines[0] = line17;
    lines[1] = line22;
    lines[2] = line23;
    lines[3] = line24;

    /* Request GPIO lines as outputs */
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    for (int i = 0; i < 4; i++) {
