        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            cleanup(0);
            return 1;
        }
    }

    /* Main loop */
    while (1) {
        for (int i = 0; i < 4; i++) {
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
