#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO4 4
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17, *line18;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

static void set_gpio_state(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
    }
}

int main()
{
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 50 milliseconds

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Setup GPIO lines */
    if (setup_gpio(GPIO4, &line4) < 0 ||
        setup_gpio(GPIO17, &line17) < 0 ||
        setup_gpio(GPIO18, &line18) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    for (int i = 0; i < 5 && !terminate; ++i) {
        set_gpio_state(line4, 1);
        set_gpio_state(line17, 0);
        set_gpio_state(line18, 1);
        printf("Cycle %d: GPIO4=1, GPIO17=0, GPIO18=1\n", i + 1);
        nanosleep(&sleep_time, NULL);

        set_gpio_state(line4, 0);
        set_gpio_state(line17, 1);
        set_gpio_state(line18, 0);
        printf("Cycle %d: GPIO4=0, GPIO17=1, GPIO18=0\n", i + 1);
        nanosleep(&sleep_time, NULL);
    }

    /* Cleanup GPIO lines */
    cleanup_gpio(line4);
    cleanup_gpio(line17);
    cleanup_gpio(line18);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return terminate ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PWM 17
#define GPIO_DUTY 27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output for PWM
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Set GPIO 27 as output for duty cycle
    gpioSetMode(GPIO_DUTY, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PWM, 255);

    // Set PWM duty cycle (initial value)
    gpioPWM(GPIO_PWM, 128); // 50% duty cycle
    gpioWrite(GPIO_DUTY, 1); // Set GPIO 27 HIGH

    // Print the state
    printf("GPIO %d PWM: %d, GPIO %d Duty Cycle: %d\n", GPIO_PWM, 128, GPIO_DUTY, 1);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Keep the program running until a signal is received
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Stop PWM
    gpioPWM(GPIO_PWM, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

