#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Cycle duration (seconds)
#define CYCLE_DURATION 60

// Number of cycles
#define NUM_CYCLES 5

// Global variable to track cycle count
volatile int cycle_count = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Stop PWM on all pins
    gpioPWM(GPIO_4, 0);
    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_27, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_27, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_4, PWM_RANGE);
    gpioSetPWMrange(GPIO_17, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);
    gpioSetPWMrange(GPIO_27, PWM_RANGE);

    // Set PWM duty cycle (example: 50%)
    gpioPWM(GPIO_4, 128);
    gpioPWM(GPIO_17, 128);
    gpioPWM(GPIO_18, 128);
    gpioPWM(GPIO_27, 128);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Increment cycle count
        cycle_count++;

        // Print cycle information
        printf("Cycle %d: GPIO 4: %d, GPIO 17: %d, GPIO 18: %d, GPIO 27: %d\n",
               cycle_count, gpioRead(GPIO_4), gpioRead(GPIO_17), gpioRead(GPIO_18), gpioRead(GPIO_27));

        // Wait for the cycle duration
        sleep(CYCLE_DURATION);

        // Check if all cycles have been completed
        if (cycle_count >= NUM_CYCLES) {
            // Stop PWM on all pins
            gpioPWM(GPIO_4, 0);
            gpioPWM(GPIO_17, 0);
            gpioPWM(GPIO_18, 0);
            gpioPWM(GPIO_27, 0);

            // Terminate pigpio
            gpioTerminate();

            return 0;
        }
    }

    return 0;
}

