// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop PWM on all pins
    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_22, 0);
    gpioPWM(GPIO_23, 0);
    gpioPWM(GPIO_24, 0);
    gpioPWM(GPIO_25, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_22, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_23, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_24, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_25, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_17, 255);
    gpioSetPWMrange(GPIO_18, 255);
    gpioSetPWMrange(GPIO_22, 255);
    gpioSetPWMrange(GPIO_23, 255);
    gpioSetPWMrange(GPIO_24, 255);
    gpioSetPWMrange(GPIO_25, 255);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate PWM values (0-255)
        for (int i = 0; i <= 255; i++) {
            // Set PWM duty cycle
            gpioPWM(GPIO_17, i);
            gpioPWM(GPIO_18, i);
            gpioPWM(GPIO_22, i);
            gpioPWM(GPIO_23, i);
            gpioPWM(GPIO_24, i);
            gpioPWM(GPIO_25, i);

