            printf("GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d, GPIO 25: %d\n", i, i, i, i, i, i);

            // Delay for 50ms
            gpioDelay(50000);
        }

        // Generate PWM values (255-0)
        for (int i = 255; i >= 0; i--) {
            // Set PWM duty cycle
            gpioPWM(GPIO_17, i);
            gpioPWM(GPIO_18, i);
            gpioPWM(GPIO_22, i);
            gpioPWM(GPIO_23, i);
