#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 17
#define MAX_TIMINGS 85

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int data[MAX_TIMINGS] = {0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout

    gpioSetMode(gpio, PI_INPUT);

    /* Wait for the DHT22 to pull the line low */
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Check every 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    /* Wait for the DHT22 to pull the line high */
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Check every 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    /* Wait for the DHT22 to pull the line low again */
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Check every 1ms
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100ms
    }

    /* Read the data pulses */
    for (i = 0; i < MAX_TIMINGS; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Check every 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100ms
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Check every 1ms
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100ms
        }
        long end = gpioTick();

        data[i] = end - start;
    }

    /* Decode the data */
    unsigned int raw_humidity = 0;
    unsigned int raw_temperature = 0;
    unsigned int checksum = 0;

    for (i = 0; i < 16; i++) {
        raw_humidity <<= 1;
        if (data[2 * i + 2] > 50) raw_humidity |= 1;
    }

    for (i = 0; i < 16; i++) {
        raw_temperature <<= 1;
        if (data[2 * i + 18] > 50) raw_temperature |= 1;
    }

    for (i = 0; i < 8; i++) {
        checksum <<= 1;
        if (data[2 * i + 34] > 50) checksum |= 1;
    }

    /* Validate the checksum */
    if (((raw_humidity >> 8) + (raw_humidity & 0xFF) + (raw_temperature >> 8) + (raw_temperature & 0xFF)) != checksum) {
        return -1; // Checksum failure
    }

    /* Convert the data to temperature and humidity */
    *humidity = (float)((raw_humidity >> 8) + (raw_humidity & 0xFF)) / 10.0;
    *temperature = (float)(((raw_temperature >> 8) + (raw_temperature & 0xFF)) & 0x7F) / 10.0;
    if (raw_temperature & 0x80) *temperature *= -1;

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht22_data(DHT22_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        sleep(60);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins (BCM numbering)
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23

// Define the number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line8, *line9, *line10, *line11, *line23;

// Function prototypes
int setup_gpio(int gpio_pin);
int set_gpio_value(struct gpiod_line *line, int value);
int cleanup_gpio(struct gpiod_line *line);
void cleanup_handler(int signum);

// Signal handler for Ctrl+C
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Close GPIO lines
    if (line8) cleanup_gpio(line8);
    if (line9) cleanup_gpio(line9);
    if (line10) cleanup_gpio(line10);
    if (line11) cleanup_gpio(line11);
    if (line23) cleanup_gpio(line23);

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set up a GPIO pin
int setup_gpio(int gpio_pin) {
    struct gpiod_line_request_config config;
    int ret;

    // Request the GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    switch (gpio_pin) {
        case GPIO_8:
            ret = gpiod_line_request(line8, &config, 0);
            break;
        case GPIO_9:
            ret = gpiod_line_request(line9, &config, 0);
            break;
        case GPIO_10:
            ret = gpiod_line_request(line10, &config, 0);
            break;
        case GPIO_11:
            ret = gpiod_line_request(line11, &config, 0);
            break;
        case GPIO_23:
            ret = gpiod_line_request(line23, &config, 0);
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
            return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to cleanup a GPIO pin
int cleanup_gpio(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

int main() {
    int i, j;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line9 = gpiod_chip_get_line(chip, GPIO_9);
    line10 = gpiod_chip_get_line(chip, GPIO_10);
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line23 = gpiod_chip_get_line(chip, GPIO_23);

    if (!line8 || !line9 || !line10 || !line11 || !line23) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_handler(0); // Call cleanup handler before exiting
        return 1;
    }

    // Set up GPIO pins
    if (setup_gpio(GPIO_8) || setup_gpio(GPIO_9) || setup_gpio(GPIO_10) || setup_gpio(GPIO_11) || setup_gpio(GPIO_23)) {
        cleanup_handler(0);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO values for each cycle
        for (j = 0; j < 5; j++) {
            set_gpio_value(line8, j % 2);
            set_gpio_value(line9, (j + 1) % 2);
            set_gpio_value(line10, (j + 2) % 2);
            set_gpio_value(line11, (j + 3) % 2);
            set_gpio_value(line23, (j + 4) % 2);

            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Format timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print timestamp and GPIO values
            printf("%s - GPIO 8: %d, GPIO 9: %d, GPIO 10: %d, GPIO 11: %d, GPIO 23: %d\n",
                   timestamp, j % 2, (j + 1) % 2, (j + 2) % 2, (j + 3) % 2, (j + 4) % 2);

            sleep(1); // Wait for 1 second
        }
    }

    // Cleanup and exit
    cleanup_handler(0);
    return 0;
}

