    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    /* Request GPIO line for output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return 1;
    }

    /* Main loop */
    while (1) {
        /* Toggle the state */
        current_state = !current_state;

        /* Set the GPIO line value */
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            cleanup();
            return 1;
        }

        /* Print the state */
        printf("GPIO %d is now %d\n", GPIO_PIN, current_state);

        /* Wait for 2 seconds */
        sleep(2);
    }

    return 0;
}

