#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize SPI
int spi_init(spi_config_t *config) {
    config->fd = open(SPI_DEVICE, O_RDWR);
    if (config->fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    if (ioctl(config->fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(config->fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(config->fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(config->fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(config->fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(config->fd);
        return -1;
    }

    return 0;
}

// Function to read data from MAX31855
int read_max31855(int fd, uint32_t *data) {
    uint8_t tx_buf[4] = {0}; // Dummy data for reading
    uint8_t rx_buf[4];

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *data = (rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3];
    return 0;
}

// Function to process MAX31855 data
void process_max31855(uint32_t data, float *internal_temp, float *external_temp) {
    // Check for fault
    if (data & 0x00000007) {
        fprintf(stderr, "Fault detected: ");
        if (data & 0x00000001) fprintf(stderr, "Open circuit\n");
        if (data & 0x00000002) fprintf(stderr, "Short to GND\n");
        if (data & 0x00000004) fprintf(stderr, "Short to VCC\n");
        *internal_temp = -999.0; // Indicate error
        *external_temp = -999.0; // Indicate error
        return;
    }

    // Extract internal temperature
    int16_t internal = (data >> 18) & 0x3FFF; // Mask and shift
    if (internal & 0x2000) internal |= 0xC000; // Sign extend
    *internal_temp = internal * 0.0625;

    // Extract external temperature
    int16_t external = (data >> 4) & 0x3FFF; // Mask and shift
    if (external & 0x2000) external |= 0xC000; // Sign extend
    *external_temp = external * 0.25;
}

// Function to print temperature data
void print_temperature(float internal_temp, float external_temp) {
    printf("Internal Temperature: %.2f C, External Temperature: %.2f C\n", internal_temp, external_temp);
}

int main() {
    spi_config_t spi_config;

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init(&spi_config) < 0) {
        return 1;
    }
    spi_fd = spi_config.fd; // Store the file descriptor

    uint32_t raw_data;
    float internal_temperature, external_temperature;

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_config.fd, &raw_data) == 0) {
            process_max31855(raw_data, &internal_temperature, &external_temperature);
            print_temperature(internal_temperature, external_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature data.\n");
        }

        sleep(1); // Read every 1 second
    }

    // Close SPI device
    close(spi_config.fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO17)");
        goto close_chip;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        perror("gpiod_chip_get_line (GPIO18)");
        goto close_line17;
    }

    ret = gpiod_line_request_output(line17, "myprog", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        goto close_line18;
    }

    ret = gpiod_line_request_output(line18, "myprog", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        goto release_line17;
    }

    return 0;

release_line17:
    gpiod_line_release(line17);
close_line18:
    gpiod_line_release(line18);
close_line17:
    gpiod_line_release(line17);
close_chip:
    gpiod_chip_close(chip);
    return -1;
}

static void cleanup_gpio(void)
{
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return EXIT_FAILURE;
    }

    printf("GPIO setup complete.  Running...\n");

    while (!terminate) {
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break;
        }

        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break;
        }

        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            break;
        }

        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO18)");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("Cleaning up GPIO...\n");
    cleanup_gpio();
    printf("Exiting.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Generates a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Main function
int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("HC-SR04 Distance Sensor\n");

    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo or timeout
        echo_received = 0; // Reset flag
        int timeout_count = 0;
        while (echo_received < 2 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
        }

        if (echo_received == 2) {
            // Calculate pulse duration
            int pulse_duration = echo_end_tick - echo_start_tick;

            // Calculate distance in centimeters
            float distance = (pulse_duration / 1000000.0) * SPEED_OF_SOUND / 2.0;

            // Print the distance
            printf("Distance: %.2f cm\n", distance);

            // Control LED based on distance
            if (distance < 20.0) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }
        } else {
            // Timeout occurred
            fprintf(stderr, "Timeout waiting for echo\n");
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(100); // Delay between measurements
    }

    return 0;
}

