// BMP280 I2C address
#define BMP280_I2C_ADDR 0x03

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from a BMP280 register
int bmp280_read_register(int fd, uint8_t reg_addr) {
    uint8_t buf[1];
    buf[0] = reg_addr;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to a BMP280 register
int bmp280_write_register(int fd, uint8_t reg_addr, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int bmp280_read_calibration_data(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3, uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3, int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6, int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t buf[26];

    // Read calibration data from registers 0x88 to 0xA1
    for (int i = 0; i < 26; i++) {
        int reg = BMP280_REG_CALIB_00 + i;
        buf[i] = bmp280_read_register(fd, reg);
        if (buf[i] == -1) {
            fprintf(stderr, "Error reading calibration data at register 0x%02X\n", reg);
            return -1;
        }
    }

    *dig_T1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *dig_T2 = (int16_t)buf[2] | ((int16_t)buf[3] << 8);
    *dig_T3 = (int16_t)buf[4] | ((int16_t)buf[5] << 8);
    *dig_P1 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    *dig_P2 = (int16_t)buf[8] | ((int16_t)buf[9] << 8);
    *dig_P3 = (int16_t)buf[10] | ((int16_t)buf[11] << 8);
    *dig_P4 = (int16_t)buf[12] | ((int16_t)buf[13] << 8);
    *dig_P5 = (int16_t)buf[14] | ((int16_t)buf[15] << 8);
    *dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    *dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    *dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    *dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Function to read temperature and pressure data from the BMP280
int bmp280_read_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t buf[6];

    // Read pressure and temperature data from registers 0xF7 to 0xFC
    for (int i = 0; i < 6; i++) {
        int reg = BMP280_REG_PRESS_MSB + i;
        buf[i] = bmp280_read_register(fd, reg);
        if (buf[i] == -1) {
            fprintf(stderr, "Error reading data at register 0x%02X\n", reg);
            return -1;
        }
    }

    *pressure = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *temperature = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);

    return 0;
}

// Function to compensate temperature
double bmp280_compensate_temperature(int32_t adc_T, uint16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    double var1, var2, T;
    var1 = (((double)adc_T) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)adc_T) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)adc_T) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    *t_fine = (int32_t)(var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
double bmp280_compensate_pressure(int32_t adc_P, uint16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9, int32_t t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;
    return p;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
