#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "myapp", GPIO_VALUE) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {1, 0}; /* 1 second */
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, GPIO_VALUE);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    close(i2c_fd);
    exit(0);
}

// Function to write a byte to a VEML7700 register
int veml7700_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VEML7700 register
int veml7700_read_register(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure the VEML7700 (example configuration: integration time = 100ms, gain = 1/8)
    if (veml7700_write_register(i2c_fd, VEML7700_ALS_CONF, 0x02) < 0) { // IT = 100ms, Gain = 1/8
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data;

        // Read ALS data
        if (veml7700_read_register(i2c_fd, VEML7700_ALS, &als_data) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Print the ALS data
        printf("ALS: %u\n", als_data);

        // Wait for 0.5 seconds
        usleep(500000); // 500000 microseconds = 0.5 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_PATH "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define TIMEOUT_SEC 1
#define TIMEOUT_USEC 0

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int setup_serial_port(const char *device_path, speed_t baud_rate) {
    int fd = open(device_path, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    serial_fd = setup_serial_port(DEVICE_PATH, BAUD_RATE);
    if (serial_fd == -1) {
        return 1;
    }

    char buffer[256];
    ssize_t bytes_read;
    time_t start_time = time(NULL);

    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(serial_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;

        int select_result = select(serial_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("Error in select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred
            if (time(NULL) - start_time > 5) {
                fprintf(stderr, "Timeout waiting for data. Exiting.\n");
                break;
            }
            continue; // Retry
        } else {
            start_time = time(NULL);
            bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received: %s", buffer);
            } else if (bytes_read == -1) {
                perror("Error reading from serial port");
                break;
            }
        }
    }

    if (serial_fd != -1) {
        close(serial_fd);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "hc-sr04", 0);
    if (ret < 0) {
        perror("Error requesting trigger line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "hc-sr04");
    if (ret < 0) {
        perror("Error requesting echo line for input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger a 10us pulse on the trigger pin
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    struct timespec ts = {0, 10}; // 10 microseconds
    nanosleep(&ts, NULL);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo to go high
    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }
    while (ret == 0) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to go low
    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }
    while (ret == 1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int ret;
    long pulse_width;
    double distance;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        pulse_width = measure_pulse_width();

        // Check for timeout
        if (pulse_width < 0) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Validate the distance
        if (distance > 0 && distance < 400) { // Reasonable range: 0-400 cm
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        // Wait 0.5 seconds
        struct timespec ts = {0, 500000000}; // 0.5 seconds
        nanosleep(&ts, NULL);
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

