#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set to measure mode)
    if (i2c_write_reg(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error initializing ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print accelerometer data
    while (1) {
        // Read accelerometer data
        int16_t x = (i2c_read_reg(i2c_fd, ADXL345_DATAX0) | (i2c_read_reg(i2c_fd, ADXL345_DATAX1) << 8));
        int16_t y = (i2c_read_reg(i2c_fd, ADXL345_DATAY0) | (i2c_read_reg(i2c_fd, ADXL345_DATAY1) << 8));
        int16_t z = (i2c_read_reg(i2c_fd, ADXL345_DATAZ0) | (i2c_read_reg(i2c_fd, ADXL345_DATAZ1) << 8));

        // Print accelerometer data
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        // Delay for 100ms
        usleep(100000);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_GPIOS 8
const int gpios[NUM_GPIOS] = {4, 17, 18, 22, 23, 24, 25, 27};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
int running = 1;

void cleanup() {
    printf("Cleaning up...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request lines for output
    for (int i = 0; i < NUM_GPIOS; i++) {
        config.consumer = "gpio_test";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            cleanup();
            return 1;
        }

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line");
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                perror("Error setting GPIO value");
                cleanup();
                return 1;
            }
            printf("GPIO %d set HIGH\n", gpios[i]);
        }
        usleep(50000); // 0.05 seconds

        for (int i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                perror("Error setting GPIO value");
                cleanup();
                return 1;
            }
            printf("GPIO %d set LOW\n", gpios[i]);
        }
        usleep(50000); // 0.05 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Set GPIO 4 HIGH
        gpioWrite(GPIO_4, 1);
        printf("GPIO 4: HIGH\n");

        // Set GPIO 17 LOW
        gpioWrite(GPIO_17, 0);
        printf("GPIO 17: LOW\n");

        // Set GPIO 27 HIGH
        gpioWrite(GPIO_27, 1);
        printf("GPIO 27: HIGH\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);

        // Set GPIO 4 LOW
        gpioWrite(GPIO_4, 0);
        printf("GPIO 4: LOW\n");

        // Set GPIO 17 HIGH
        gpioWrite(GPIO_17, 1);
        printf("GPIO 17: HIGH\n");

        // Set GPIO 27 LOW
        gpioWrite(GPIO_27, 0);
        printf("GPIO 27: LOW\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        for (i = 0; i <= PWM_RANGE; i++) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            gpioDelay(100000); // 0.1 seconds
        }
        for (i = PWM_RANGE; i >= 0; i--) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            gpioDelay(100000); // 0.1 seconds
        }
    }

    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

