static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;
    int i;

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO line 4 */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line (GPIO 4)");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line 4 as output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio4_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line4, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO 4)");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Get GPIO line 17 */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO 17)");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line 17 as output */
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio17_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request (GPIO 17)");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    for (i = 0; i < 5; i++) {
        /* Set GPIO 4 high */
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 4 high)");
            break;
        }

        /* Set GPIO 17 low */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17 low)");
            break;
        }

        printf("Cycle %d: GPIO 4 high, GPIO 17 low\n", i + 1);
        sleep(1);

        /* Set GPIO 4 low */
        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 4 low)");
            break;
        }

        /* Set GPIO 17 high */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17 high)");
            break;
        }

        printf("Cycle %d: GPIO 4 low, GPIO 17 high\n", i + 1);
        sleep(1);
    }

    /* Release GPIO lines */
    gpiod_line_release(line4);
    gpiod_line_release(line17);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("Program terminated.\n");

    return 0;
}

