// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(GPIO_4, PI_OUTPUT);

    // Set GPIO 22 as output
    gpioSetMode(GPIO_22, PI_OUTPUT);

    // Set PWM frequency for GPIO 4 (adjust as needed)
    gpioSetPWMfrequency(GPIO_4, 1000); // 1 kHz

    // Set PWM frequency for GPIO 22 (adjust as needed)
    gpioSetPWMfrequency(GPIO_22, 1000); // 1 kHz

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_4, 255);
    gpioSetPWMrange(GPIO_22, 255);

    // Set PWM duty cycle (initial value)
    gpioPWM(GPIO_4, 128); // 50% duty cycle
    gpioPWM(GPIO_22, 128); // 50% duty cycle

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Report the state
        printf("GPIO 4: %d, GPIO 22: %d\n", gpioRead(GPIO_4), gpioRead(GPIO_22));

        // Wait for 0.01 seconds
        gpioDelay(10000); // 10000 microseconds = 0.01 seconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
