#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 24
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio24/value"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    int ret;
    FILE *fp;
    char value_str[2];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio24_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set GPIO high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting GPIO value high");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Read back the value
    fp = fopen(GPIO_VALUE_PATH, "r");
    if (!fp) {
        perror("Error opening GPIO value file");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    if (fgets(value_str, sizeof(value_str), fp) == NULL) {
        perror("Error reading GPIO value");
        fclose(fp);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }
    fclose(fp);

    if (value_str[0] != '1') {
        fprintf(stderr, "Error: GPIO value is not 1 (expected 1, got %d)\n", value_str[0]);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("GPIO %d (BCM %d) is HIGH at %s\n", GPIO_PIN, GPIO_PIN, timestamp);

    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return 0;
}

