#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
    }
}

// Main function
int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for the echo pulse
        gpioDelay(TIMEOUT_US); // Wait for timeout

        // Calculate distance
        float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // in cm

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Control the LED based on distance
        if (distance < 20.0) {
            gpioWrite(LED_PIN, 1); // Turn LED on
        } else {
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        // Reset pulse width
        pulse_width = 0;

        // Delay before next measurement
        gpioDelay(100000); // 100ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

