// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM range
#define PWM_RANGE 1000

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(GPIO_18, 0); // Stop PWM on GPIO 18
    gpioPWM(GPIO_21, 0); // Stop PWM on GPIO 21
    gpioPWM(GPIO_22, 0); // Stop PWM on GPIO 22
    gpioTerminate();      // Terminate pigpio
    exit(0);              // Exit the program
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_21, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_21, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_21, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_22, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_22, PWM_RANGE);

    // Generate PWM signals
    for (int duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 100) {
        gpioPWM(GPIO_18, duty_cycle);
        gpioPWM(GPIO_21, duty_cycle);
        gpioPWM(GPIO_22, duty_cycle);
        printf("GPIO 18: %d, GPIO 21: %d, GPIO 22: %d\n", duty_cycle, duty_cycle, duty_cycle);
        usleep(100000); // 100ms delay
    }

    // Clean up and exit
    signal_handler(SIGINT);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define NUM_GPIOS 7
const int gpios[NUM_GPIOS] = {17, 18, 22, 23, 24, 25, 27};

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_GPIOS];
    int i, ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d: %s\n", gpios[i], strerror(errno));
            ret = 1;
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d: %s\n", gpios[i], strerror(errno));
            ret = 1;
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        int value = i % 2; // Alternate between 0 and 1
        ret = gpiod_line_set_value(lines[i], value);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for GPIO %d: %s\n", gpios[i], strerror(errno));
            ret = 1;
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", gpios[i], value);
    }

    sleep(1);

cleanup:
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
void set_led(int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        goto cleanup_chip;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        goto cleanup_trigger;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        goto cleanup_echo;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        goto cleanup_led;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        goto cleanup_trigger_request;
    }

    if (gpiod_line_request_output(led_line, "hc-sr04", 0) < 0) {
        perror("Error requesting LED line as output");
        goto cleanup_echo_request;
    }

    return 0;

cleanup_echo_request:
    gpiod_line_release(echo_line);
cleanup_trigger_request:
    gpiod_line_release(trigger_line);
cleanup_led:
    gpiod_line_release(led_line);
cleanup_echo:
    gpiod_line_release(echo_line);
cleanup_trigger:
    gpiod_line_release(trigger_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Trigger the HC-SR04 sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo line
long measure_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo line to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
        pulse_width++;
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo line to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
        pulse_width++;
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Set the LED state
void set_led(int state) {
    gpiod_line_set_value(led_line, state);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Distance Sensor\n");

    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            // Calculate the distance
            float distance = calculate_distance(pulse_width);

            // Set the LED based on distance
            if (distance < 20.0) {
                set_led(1); // Turn LED on
            } else {
                set_led(0); // Turn LED off
            }

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: No echo received.\n");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 16
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int dutyCycle = 0;
    while (!terminate) {
        gpioPWM(GPIO_PIN, dutyCycle);
        printf("Duty Cycle: %d\n", dutyCycle);
        dutyCycle += 50;
        if (dutyCycle > 255) {
            dutyCycle = 0;
        }
        sleep(1);
    }

    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input to avoid leaving it in output mode
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and ADC enable)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME).  2.4ms * 256 = 1.31ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Could not set integration time\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int read_tcs34725(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    // Read all color data in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data\n");
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (0x%02X): %d\n", TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t clear, red, green, blue;

        // Read color data
        if (read_tcs34725(&clear, &red, &green, &blue) == 0) {
            // Print the color data
            printf("Clear: %5d, Red: %5d, Green: %5d, Blue: %5d\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

