        gpiod_line_release(line23);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIOCHIP);
