        perror("gpiod_chip_get_line (GPIO18)");
        gpiod_chip_close(chip);
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO23);
    if (!line23) {
        perror("gpiod_chip_get_line (GPIO23)");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line18, &config, 0);
