        perror("gpiod_line_request (GPIO18)");
        gpiod_line_release(line18);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(line23, &config, 0);
    if (ret < 0) {
