struct gpiod_line *lines[NUM_GPIOS];
int current_state = 0;

void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0); // Set to low
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines and set direction to output
    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpios[i], strerror(errno));
            cleanup(0);
            return 1;
        }

        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", gpios[i], strerror(errno));
            cleanup(0);
            return 1;
        }
    }

    // Main loop: toggle GPIOs
    while (1) {
        for (int i = 0; i < NUM_GPIOS; i++) {
            ret = gpiod_line_set_value(lines[i], current_state);
            if (ret < 0) {
                fprintf(stderr, "Error setting value on line %d: %s\n", gpios[i], strerror(errno));
                cleanup(0);
                return 1;
            }
        }
        current_state = !current_state;
        printf("Toggling GPIOs to state: %d\n", current_state);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
