#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_22 22
#define GPIO_24 24

static struct gpiod_chip *chip;
static struct gpiod_line *line22, *line24;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
}

static int set_gpio_state(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Setup GPIO lines */
    if (setup_gpio(GPIO_22, &line22) < 0 || setup_gpio(GPIO_24, &line24) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO 22 to HIGH */
        if (set_gpio_state(line22, 1) < 0) {
            break;
        }
        printf("GPIO 22: HIGH\n");

        /* Wait */
        nanosleep(&sleep_time, NULL);

        /* Set GPIO 24 to LOW */
        if (set_gpio_state(line24, 0) < 0) {
            break;
        }
        printf("GPIO 24: LOW\n");

        /* Wait */
        nanosleep(&sleep_time, NULL);
    }

    /* Cleanup GPIO lines */
    cleanup_gpio(line22);
    cleanup_gpio(line24);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

