#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUDRATE B115200
#define TIMEOUT_SEC 1
#define TIMEOUT_USEC 0

volatile sig_atomic_t keep_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int setup_serial(const char *device, speed_t baudrate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baudrate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    serial_fd = setup_serial(DEVICE, BAUDRATE);
    if (serial_fd == -1) {
        return 1;
    }

    char buffer[256];
    ssize_t bytes_read;
    time_t start_time, current_time;
    double elapsed_time;

    printf("Reading from serial port %s at %d baud...\n", DEVICE, BAUDRATE);

    while (keep_running) {
        start_time = time(NULL);
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout occurred, no data received
                current_time = time(NULL);
                elapsed_time = difftime(current_time, start_time);
                if (elapsed_time >= TIMEOUT_SEC) {
                    fprintf(stderr, "Timeout waiting for data.\n");
                    keep_running = 0; // Exit on timeout
                }
            } else {
                perror("Error reading from serial port");
                keep_running = 0;
            }
        } else {
            // No data received and no error
            current_time = time(NULL);
            elapsed_time = difftime(current_time, start_time);
            if (elapsed_time >= TIMEOUT_SEC) {
                fprintf(stderr, "Timeout waiting for data.\n");
                keep_running = 0; // Exit on timeout
            }
        }
        usleep(100000); // 0.1 seconds
    }

    close(serial_fd);
    printf("Serial port closed.\n");

    return 0;
}

