static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set echo_received flag
    }
}

// Main function
int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (1) {
        // Send trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (!echo_received && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1us
            timeout_count++;
        }

        // Check if echo was received within timeout
        if (echo_received) {
            // Calculate pulse duration in microseconds
            int pulse_duration = echo_end_tick - echo_start_tick;

            // Calculate distance in centimeters
            float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;

            // Print distance
            printf("Distance: %.2f cm\n", distance);

            // Control LED based on distance
            if (distance < 20.0) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }
        } else {
            // Timeout occurred
            fprintf(stderr, "Timeout: No echo received\n");
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        // Delay before next measurement
        gpioDelay(100); // 100ms delay
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio18/value"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int read_gpio_value(int *value)
{
    FILE *fp;
    char value_str[2];

    fp = fopen(GPIO_VALUE_PATH, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fgets(value_str, sizeof(value_str), fp) == NULL) {
        perror("Failed to read GPIO value");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (value_str[0] == '0') {
        *value = 0;
    } else if (value_str[0] == '1') {
        *value = 1;
    } else {
        fprintf(stderr, "Invalid GPIO value: %s\n", value_str);
        return -1;
    }

    return 0;
}

static int check_gpio_value(int value)
{
    if (value == 0 || value == 1) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        return -1; // Invalid
    }
}

int main()
{
    int value;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms

    /* Install signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    if (gpiod_line_request_output(line, "myapp", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        if (read_gpio_value(&value) == 0) {
            if (check_gpio_value(value) == 0) {
                printf("GPIO value: %d\n", value);
            } else {
                fprintf(stderr, "Invalid GPIO value, skipping.\n");
            }
        } else {
            fprintf(stderr, "Failed to read GPIO value, skipping.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        for (i = 0; i <= PWM_RANGE; i++) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            gpioDelay(200000); // 0.2 seconds
        }
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
