#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(int gpio, int value)
{
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    line17 = gpiod_chip_get_line(chip, gpio);
    if (!line17) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_set_value(line17, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line %d value: %s\n", gpio, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    ret = setup_gpio(GPIO_17, 1);
    if (ret < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    ret = setup_gpio(GPIO_18, 0);
    if (ret < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH, GPIO %d set to LOW\n", GPIO_17, GPIO_18);

    while (!terminate) {
        sleep(1);
    }

    cleanup_gpio();
    printf("GPIO cleanup complete. Exiting.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

static struct gpiod_chip *chip;
static struct gpiod_line *line18, *line23, *line24;

static void cleanup(void)
{
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (line23) {
        gpiod_line_set_value(line23, 0);
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_set_value(line24, 0);
        gpiod_line_release(line24);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main()
{
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO lines */
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line (GPIO_18)");
        cleanup();
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line (GPIO_23)");
        cleanup();
        return 1;
    }

    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line24) {
        perror("gpiod_chip_get_line (GPIO_24)");
        cleanup();
        return 1;
    }

    /* Request GPIO lines as outputs */
    ret = gpiod_line_request_output(line18, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO_18)");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(line23, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO_23)");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(line24, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO_24)");
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (1) {
        /* Set GPIO 18 high */
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_18)");
            cleanup();
            return 1;
        }
        printf("GPIO 18: HIGH\n");

        /* Set GPIO 23 low */
        ret = gpiod_line_set_value(line23, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_23)");
            cleanup();
            return 1;
        }
        printf("GPIO 23: LOW\n");

        /* Set GPIO 24 high */
        ret = gpiod_line_set_value(line24, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_24)");
            cleanup();
            return 1;
        }
        printf("GPIO 24: HIGH\n");

        /* Wait for 0.1 seconds */
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);

        /* Set GPIO 18 low */
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_18)");
            cleanup();
            return 1;
        }
        printf("GPIO 18: LOW\n");

        /* Set GPIO 23 high */
        ret = gpiod_line_set_value(line23, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_23)");
            cleanup();
            return 1;
        }
        printf("GPIO 23: HIGH\n");

        /* Set GPIO 24 low */
        ret = gpiod_line_set_value(line24, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO_24)");
            cleanup();
            return 1;
        }
        printf("GPIO 24: LOW\n");

        /* Wait for 0.1 seconds */
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z;

        if (read_accelerometer_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        sleep(1);
    }

    // This point will not be reached unless an error occurs or the program is interrupted.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_VALUE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "myapp", GPIO_VALUE);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {0, 600000000}; // 0.6 seconds
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to %d\n", GPIO_PIN, GPIO_VALUE);

    while (!terminate) {
        ret = gpiod_line_set_value(line, GPIO_VALUE);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("Exiting cleanly\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}
